/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A24 frozen manifest: detractor–disciple (80 headwords), hand-authored. */
'use strict';
const D = globalThis.RA.D;
const Q = (w,n,s,p,a,b,c,x,type='meaning') => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:type,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M = (wrong,right,reason,type='meaning') => ({errorType:type,wrong,right,reason});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E = (origin,w) => ({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P = (w,origin,ctx,mistake,quiz) => D(w,{etymology:E(origin,w),contexts:[ctx],mistakes:[mistake],quiz});

P('detractor','detractor 来自 detract + -or；detract 源自拉丁语 detrahere“拉下、贬损”，-or 表示施事者。',C('detractor.s1','评论与评价','Although the novel sold well, one detractor called its ending shallow and said the characters never changed.','尽管这部小说销量不错，一位批评者仍称结尾肤浅，并说人物毫无变化。','Although the novel sold well / one detractor called its ending shallow / and said the characters never changed.','detractor 是可数名词；call A + 形容词表示称 A 如何。','此人公开贬低作品，符合 detractor 的“诋毁者”义。'),M('A detractor praised every part of the plan and urged the committee to adopt it.','A supporter praised every part of the plan and urged the committee to adopt it.','全力称赞并支持计划的人是 supporter；detractor 指贬低或反对者。'),[Q('detractor',1,1,'A detractor of a proposal is most likely to?','criticize it','fund it','translate it','detractor 指贬低或批评某人、某事的人。'),Q('detractor',2,1,'The reviewer is called a detractor because she?','focuses on flaws and speaks against the film','buys tickets for the premiere','writes the film’s music','公开指出缺点并反对作品，体现 detractor。'),Q('detractor',3,1,'Choose the closest contrast to detractor.','advocate','opponent','critic','advocate 是支持者，与 detractor 的反对、贬低相对。'),Q('detractor',4,1,'“Even a detractor admitted the bridge was safe” implies that person usually?','speaks negatively about it','designed it','maintains it','让步语气说明 detractor 通常持批评立场。')]);
P('detrimental','detrimental 由 detriment（损害）加形容词后缀 -al 构成，源自拉丁语 detrimentum“损失、伤害”。',C('detrimental.s1','健康','Several nights of severe sleep loss can be detrimental to concentration, so the clinic advises patients to keep a steady bedtime.','连续几晚严重缺觉会损害注意力，因此诊所建议患者保持固定就寝时间。','Several nights of severe sleep loss can be detrimental to concentration / so the clinic advises patients to keep a steady bedtime.','be detrimental to 是常见结构；to 后接名词或动名词。','缺觉会造成注意力受损，对应“有害的”义 s1。'),M('Skipping meals is detrimental for your health because it improves your nutrition.','Skipping meals can be detrimental to your health because it may deprive you of needed nutrients.','原句把“有害”与“改善营养”矛盾地并列；改写后因果一致且用常见 detrimental to。'),[Q('detrimental',1,1,'If a habit is detrimental to health, it is?','harmful','essential','harmless','detrimental 表示造成损害。'),Q('detrimental',2,2,'A policy may be detrimental to small firms if it?','raises their costs and reduces their chances of survival','gives them free equipment','simplifies their paperwork','引发损失的不利结果对应 s2。'),Q('detrimental',3,1,'Complete the natural collocation: “detrimental ___ sleep.”','to','at','from','形容词 detrimental 通常与 to 搭配。'),Q('detrimental',4,1,'Which change is detrimental to a garden?','polluting the soil with toxic waste','adding suitable compost','watering a dry seedling','有毒污染会损害花园。')]);
P('detritus','detritus 借自拉丁语 detritus“磨损下来的东西”，与 deterere“磨损”有关；可指自然碎屑，也可指过程后的废弃残留。',C('detritus.s2','活动清理','After the parade, volunteers swept confetti, paper cups, and other detritus from the square before the market opened.','游行结束后，志愿者在集市开门前把广场上的彩纸、纸杯和其他残留杂物清扫干净。','After the parade / volunteers swept confetti, paper cups, and other detritus from the square / before the market opened.','detritus 作不可数集合名词；sweep A from B 表示从 B 清除 A。','彩纸与纸杯是活动过后的废弃残留，属于 s2。'),M('The hikers left no detritus behind and packed every wrapper out of the park.','The hikers left no litter behind and packed every wrapper out of the park.','句意是没有留下垃圾，与“留下残留物”矛盾；litter 更适合和 no 呼应。'),[Q('detritus',1,2,'After a festival, bottles and scraps on the ground are?','detritus','bedrock','wildlife','活动后的垃圾残留属于 detritus。'),Q('detritus',2,1,'In geology, detritus may consist of?','loose rock fragments worn away by erosion','newly formed gemstones only','a solid sheet of untouched bedrock','地质义指风化侵蚀形成的松散碎屑。'),Q('detritus',3,2,'A team clears detritus from a site by?','removing leftover debris','adding fresh decorations','measuring the air temperature','清除 detritus 即移走残余杂物。'),Q('detritus',4,1,'Which phrase best fits the natural sense?','river detritus deposited downstream','a flock of migrating birds','a layer of living grass','水流搬运并沉积的岩屑可称 detritus。')]);
P('devaluation','devaluation 由 de-（降低）+ value + -ation 构成；经济术语指货币官方贬值，亦可比喻某事物受重视程度下降。',C('devaluation.s1','国际金融','The central bank announced a devaluation of the currency, making imported fuel more expensive in local shops the following week.','央行宣布本币贬值，随后一周当地商店里的进口燃料变得更贵。','The central bank announced a devaluation of the currency / making imported fuel more expensive / in local shops the following week.','devaluation of + 货币表示该货币贬值；making 短语说明结果。','进口品因汇率调整而涨价，符合货币价值下降义 s1。'),M('The devaluation strengthened the currency, so one unit bought more foreign money.','The revaluation strengthened the currency, so one unit bought more foreign money.','币值走强、购买力提高是升值而非 devaluation；将术语改为 revaluation。'),[Q('devaluation',1,1,'A currency devaluation generally makes that currency?','worth less relative to others','officially backed by more gold','impossible to exchange','devaluation 是货币相对价值的正式下调。'),Q('devaluation',2,2,'The devaluation of public service means people?','regard it as less important than before','give it a higher social status','have made it more expensive','比喻义表示某事物受到的重视降低。'),Q('devaluation',3,1,'A tourist needs more local currency to buy the same imported goods after?','a devaluation','a harvest','a promotion','货币贬值会削弱本币购买进口品的能力。'),Q('devaluation',4,1,'Which is closest to the economic meaning?','an official cut in a currency’s value','a rise in a company’s share price','a ban on foreign travel','官方下调货币汇率价值即 devaluation。')]);
P('developer','developer 源于 develop + -er；develop 经古法语来自拉丁语 evolvere 的词族，现代 developer 可指软件开发者或土地开发商。',C('developer.s1','软件行业','The developer released a patch that fixed the login flaw, then asked users to install it before the next security scan.','开发者发布了修复登录漏洞的补丁，并提醒用户在下一次安全扫描前安装。','The developer released a patch that fixed the login flaw / then asked users to install it / before the next security scan.','developer 指实施开发的人或公司；that 引导定语从句修饰 patch。','发布软件补丁的主体是软件开发者，符合 s1。'),M('The developer wrote the application’s code but had never designed or built any software.','The developer wrote the application’s code and had designed and built the software.','编写应用程序代码属于软件开发；后半句否认该工作，与 developer 身份矛盾。'),[Q('developer',1,1,'A software developer usually?','designs or builds computer programs','repairs roads for a living only','sells vegetables at a market','软件 developer 负责设计或开发程序。'),Q('developer',2,1,'A property developer is likely to?','build homes or commercial sites on land','diagnose computer viruses','write a newspaper review','地产 developer 开发土地并建造物业。'),Q('developer',3,1,'A team member who writes new app features is the?','developer','tenant','auditor','编写应用功能的是 developer。'),Q('developer',4,1,'In a project report, “the developer fixed the bug” most likely means?','the person who builds the software corrected an error','the building’s landlord collected rent','the user changed a password','软件开发者修复程序错误。')]);
P('developmental','developmental 由 development + -al 构成，指与成长、发育或发展过程有关；development 的词源与 develop 同源。',C('developmental.s1','儿童教育','The school uses short, age-appropriate tasks because children’s developmental abilities change rapidly during the early years.','学校使用简短且符合年龄的任务，因为儿童早期的发育能力变化很快。','The school uses short, age-appropriate tasks / because children’s developmental abilities change rapidly / during the early years.','developmental 修饰 abilities；because 引导原因从句。','能力随儿童成长阶段变化，属于发育或发展相关义。'),M('The developmental checklist was intended to assess adult shoe sizes, not growth or learning.','The sizing checklist was intended to record adult shoe sizes, not growth or learning.','成人鞋码与成长评估无关；删去 developmental 可避免误称其为发育评估。'),[Q('developmental',1,1,'A developmental milestone concerns?','a stage in growth or learning','the price of a building','the history of a currency','developmental 指成长或发育过程中的阶段。'),Q('developmental',2,1,'A developmental study of language in toddlers would track?','how their speaking ability grows','how their shoes are manufactured','how much their parents earn','幼儿语言能力的变化是发展研究主题。'),Q('developmental',3,1,'Which adjective fits a chart showing age-related child skills?','developmental','metallic','accidental','发展图表可称 developmental chart。'),Q('developmental',4,1,'In “developmental delay,” the adjective refers to?','the pace of a person’s growth or skill acquisition','the layout of a building site','a discount on a product','developmental 描述成长或技能发展的节奏。')]);
P('deviance','deviance 由 deviant + -ance 构成，源于拉丁语 deviare“偏离道路”；社会学中指偏离群体规范的行为或状态。',C('deviance.s1','社会学','The seminar examined how the same act can be labelled deviance in one community but accepted as normal in another.','研讨课探讨同一行为如何在一个社群中被视为越轨，却在另一个社群中被当作正常。','The seminar examined how the same act can be labelled deviance in one community / but accepted as normal in another.','deviance 作不可数名词；how 引导宾语从句。','“越轨”取决于群体规范，例句体现偏离社会常态的行为。'),M('The researcher defined deviance as behaviour that always follows every group rule.','The researcher defined conformity as behaviour that follows group rules.','完全遵守群体规范是 conformity；deviance 是偏离规范。'),[Q('deviance',1,1,'In sociology, deviance is behaviour that?','departs from a group’s accepted norms','matches every local rule','is always biologically inherited','deviance 指偏离群体规范的行为。'),Q('deviance',2,1,'The same act may count as deviance in one society but not another because?','norms differ between groups','all societies have identical laws','the act changes its spelling','不同群体规范不同，越轨判断也可能不同。'),Q('deviance',3,1,'A study of deviance would most likely examine?','social reactions to rule-breaking','the chemical structure of salt','the route of a migrating bird','越轨研究关注偏离规范及其社会反应。'),Q('deviance',4,1,'The opposite idea closest to deviance is?','conformity','disorder','departure','遵从群体规范的 conformity 与 deviance 相对。')]);
P('deviant','deviant 来自 deviate + -ant；deviate 源自拉丁语 deviare“离开道路”，可作形容词或名词，指偏离规范的人或事。',C('deviant.s2','行为研究','Rather than labelling the teenager a deviant, the counselor asked what pressures had led him to break the school’s rules.','咨询师没有给这名少年贴上越轨者标签，而是询问哪些压力导致他违反校规。','Rather than labelling the teenager a deviant / the counselor asked what pressures had led him to break the school’s rules.','deviant 作可数名词；rather than 后可接动名词。','此处指被群体视作偏离常规的人，使用名词义 s2。'),M('The report called the student deviant because he followed every school rule without exception.','The report called the student conscientious because he followed every school rule without exception.','始终遵守校规不能作为“偏离规范”的理由；conscientious 更合乎描述。'),[Q('deviant',1,1,'A deviant action is?','outside what a group considers normal','required by every rule','identical to the average in all ways','形容词 deviant 指偏离常规。'),Q('deviant',2,2,'If a newspaper calls someone “a deviant,” it uses deviant as?','a noun for a person considered outside the norm','a verb meaning to measure','an adverb of direction','这里 deviant 是指人的名词。'),Q('deviant',3,1,'Which behaviour might a community label deviant?','breaking a strongly enforced local norm','following a routine everyone accepts','using the approved entrance','偏离社会规范的行为可能被称为 deviant。'),Q('deviant',4,2,'A deviant is described relative to?','the norms of a group','the person’s shoe size','the weather forecast','“越轨者”身份取决于群体规范。')]);
P('deviation','deviation 由 deviate + -ion 构成，词根来自拉丁语 deviare“偏离道路”；表示偏离规则、计划或统计标准的行为或差值。',C('deviation.s2','统计学','The sensor’s reading showed a deviation of two millimeters from the calibration standard, so the technician adjusted it before testing.','传感器读数与校准标准相差两毫米，因此技术人员在测试前进行了调整。','The sensor’s reading showed a deviation of two millimeters from the calibration standard / so the technician adjusted it before testing.','deviation from + 标准；of two millimeters 给出偏差幅度。','读数和基准之间的量差是 deviation 的统计/测量义 s2。'),M('The recorded deviation was exactly zero, so the measurement differed from the standard by five centimeters.','The recorded deviation was five centimeters, so the measurement differed from the standard by that amount.','偏差为零意味着与标准一致，不可能同时相差五厘米。'),[Q('deviation',1,1,'A deviation from a travel plan is?','a departure from the planned route','the plan’s exact repetition','a receipt for a ticket','deviation 可表示偏离计划或路线。'),Q('deviation',2,2,'In measurement, a deviation of 2 mm is?','the amount a reading differs from its standard','the total length of the instrument','the name of the measured object','测量义指读数与标准之间的差值。'),Q('deviation',3,1,'A scientist notes a deviation because the result?','does not match the expected value exactly','proves there was no measurement','has no unit or comparison','偏差描述结果未完全符合预期或标准。'),Q('deviation',4,1,'Which phrase is idiomatic?','a deviation from the original route','a deviation at the original route','a deviation into the original route','常用结构是 deviation from。')]);
P('devious','devious 与古法语 devier/拉丁语 deviare“离开正路”有关；可比喻不坦率狡猾，也可指路线曲折迂回。',C('devious.s1','商业谈判','The auditor uncovered a devious scheme in which the supplier split invoices to hide payments from the review team.','审计员揭露了供应商的一套狡猾伎俩：拆分发票以向审查组隐瞒付款。','The auditor uncovered a devious scheme / in which the supplier split invoices / to hide payments from the review team.','devious 修饰 scheme；in which 引出方案的具体做法。','故意拆开发票隐瞒付款，体现不坦率、欺诈的 s1。'),M('The hikers chose a devious route that went straight from the gate to the summit with no turns.','The hikers chose a direct route that went straight from the gate to the summit with no turns.','毫无弯曲的直线路线与 devious 的曲折义相反；direct 是恰当替换。'),[Q('devious',1,1,'A devious plan is likely to involve?','dishonest tricks','open and direct discussion','a harmless straight line','devious 可指狡诈、不坦诚的。'),Q('devious',2,2,'A devious path through the hills is?','winding rather than direct','perfectly straight','closed to all walkers','路线义 devious 指曲折迂回。'),Q('devious',3,1,'Which person acts deviously?','someone who hides the real purpose to mislead others','someone who states the terms plainly','someone who follows a marked path','隐瞒真实目的以误导他人是狡猾做法。'),Q('devious',4,1,'“A devious route to the village” most naturally describes a route that?','takes a roundabout course','is the shortest straight road','is completely imaginary','迂回路线不是直达路线。')]);
P('devouringly','devouringly 是 devouring（devour 的现在分词）加副词后缀 -ly；devour 可追溯至古法语 devorer、拉丁语 devorare“吞下、吞食”。',C('devouringly.s1','阅读与兴趣','She read the travel journal devouringly, turning page after page until the station announcement interrupted her.','她如饥似渴地读着旅行日记，一页接一页，直到车站广播打断她。','She read the travel journal devouringly / turning page after page / until the station announcement interrupted her.','devouringly 修饰 read，表示投入而急切地阅读；until 引导时间从句。','此处是引申的“如饥似渴、全神贯注地”义，不是字面吞食。'),M('The children devouringly nibbled one tiny cracker over the entire afternoon without interest.','The children listlessly nibbled one tiny cracker over the entire afternoon without interest.','devouringly 表示急切贪婪或全神贯注，与漫不经心地慢慢啃不符。'),[Q('devouringly',1,1,'To read devouringly is to read?','with eager, absorbed attention','without opening the book','only by skipping every page','副词 devouringly 比喻如饥似渴地投入阅读。'),Q('devouringly',2,1,'A diner who eats devouringly probably?','eats hungrily and quickly','refuses all food','carefully studies the menu but leaves','devouringly 可形容贪婪急切地吃。'),Q('devouringly',3,1,'Which adverb best fits someone absorbed in a gripping novel?','devouringly','reluctantly','silently only because of a rule','沉浸读小说可形容 devouringly。'),Q('devouringly',4,1,'The suffix -ly in devouringly chiefly makes it?','an adverb describing how an action is done','a plural noun','a past-tense verb','-ly 把 devouring 形式构成方式副词。')]);
P('devout','devout 源自古法语 devot、拉丁语 devotus（devovere“奉献、立誓”的过去分词），既指虔诚，也可指衷心诚挚。',C('devout.s1','宗教生活','A devout Buddhist visited the temple before dawn each week and quietly joined the community in prayer.','一位虔诚的佛教徒每周黎明前到寺庙，静静地与社群一同祈祷。','A devout Buddhist visited the temple before dawn each week / and quietly joined the community in prayer.','devout 修饰 Buddhist；before dawn 表示清晨前。','定期到寺庙并祈祷体现严肃而虔诚的宗教信仰。'),M('He was devout about the faith but never believed in it, practised it, or attended services.','He was indifferent to the faith and never believed in it, practised it, or attended services.','不相信、不实践信仰的人不符合 devout 的虔诚义。'),[Q('devout',1,1,'A devout worshipper is?','deeply committed to religious belief and practice','openly hostile to every religion','interested only in religious architecture','devout 指虔诚信仰并认真实践。'),Q('devout',2,2,'“A devout wish for their success” uses devout to mean?','sincere and strongly felt','officially forbidden','mathematically exact','devout 也可形容诚挚热切的感情。'),Q('devout',3,1,'Which person is most clearly devout?','someone who faithfully observes the practices of a religion','someone who mocks every act of worship','someone who sells tickets near a temple','虔诚者认真持守宗教实践。'),Q('devout',4,1,'The closest opposite of a devout believer is?','an irreligious or uncommitted person','a devoted practitioner','a sincere worshipper','缺乏宗教信仰或投入与 devout 相反。')]);
P('dexterity','dexterity 经法语 dexterité 源自拉丁语 dexteritas；dexter 表示“右侧、灵巧”，现代指手部灵巧或处事机敏。',C('dexterity.s1','手工技艺','The watchmaker’s dexterity let her replace the tiny spring without bending the delicate metal contacts around it.','制表师手法灵巧，能更换细小弹簧而不弄弯周围脆弱的金属触点。','The watchmaker’s dexterity let her replace the tiny spring / without bending the delicate metal contacts around it.','dexterity 作不可数名词；let + 宾语 + 动词原形。','精细更换弹簧需要迅速准确的手部动作，符合 s1。'),M('His dexterity with the tiny screws made him drop each one and damage the watch.','His clumsiness with the tiny screws made him drop each one and damage the watch.','不断掉落零件表现笨拙而非 dexterity；替换为 clumsiness 才与结果一致。'),[Q('dexterity',1,1,'A surgeon’s manual dexterity is?','skillful, precise movement of the hands','a loud speaking voice','the ability to run long distances','dexterity 的手部义指灵巧准确地操作。'),Q('dexterity',2,2,'Social dexterity helps a negotiator?','handle people and difficult exchanges cleverly','measure a table with a ruler','memorize every street name','引申义是处事机敏、善于应对人际情境。'),Q('dexterity',3,1,'Which task most obviously requires dexterity?','threading a fine needle','watching a film','sitting in a quiet room','穿细针眼需要手部灵巧。'),Q('dexterity',4,1,'In “political dexterity,” dexterity means?','skill in dealing with people and situations','finger strength alone','a medical diagnosis','政治 dexterity 指处事灵活机敏。')]);
P('dexterous','dexterous 源自拉丁语 dexter“右侧、灵巧”，经法语进入英语；可描述手巧，也可描述处理局势机敏。',C('dexterous.s2','外交','The ambassador was dexterous in handling the dispute, acknowledging both sides’ concerns without promising what her government could not deliver.','大使处理争端很机敏：她承认双方的顾虑，却没有承诺本国政府无法兑现的事。','The ambassador was dexterous in handling the dispute / acknowledging both sides’ concerns / without promising what her government could not deliver.','be dexterous in + 名词/动名词；without 引出未做之事。','审慎地兼顾双方且不越权承诺，体现处事机敏 s2。'),M('The dexterous envoy mishandled every objection and made the negotiation much worse.','The inept envoy mishandled every objection and made the negotiation much worse.','处理不当、恶化谈判表现 inept，而非 dexterous。'),[Q('dexterous',1,1,'A dexterous craft worker can?','use tools with skill and precision','only lift heavy objects','avoid touching any material','dexterous 的常见义是手巧、操作熟练。'),Q('dexterous',2,2,'A dexterous response to a tense question is?','cleverly judged and tactful','carelessly insulting','unrelated to the question','处事义 dexterous 强调机敏、妥当地应对。'),Q('dexterous',3,1,'Which description fits a dexterous pianist?','her fingers move accurately across difficult passages','she refuses to touch the keyboard','she forgets how to read music','演奏高难乐段需要灵活准确的手指控制。'),Q('dexterous',4,2,'A politician dexterous in compromise is good at?','finding a workable way through disagreement','making every conflict worse','avoiding all discussion forever','擅长折中体现机敏处理分歧。')]);
P('diabolism','diabolism 源自晚期拉丁语 diabolismus 和希腊语 diabolos“诽谤者、魔鬼”，指魔鬼崇拜或与魔鬼相关的巫术。',C('diabolism.s1','宗教史','The historian used the word diabolism only when describing accusations of devil worship in the court records, not as a neutral name for folk medicine.','历史学家只在描述法庭记录中的魔鬼崇拜指控时使用 diabolism，而不用它中性地称呼民间医术。','The historian used the word diabolism only when describing accusations of devil worship in the court records / not as a neutral name for folk medicine.','diabolism 作不可数名词；only when 限定使用语境。','词义涉及魔鬼崇拜或相关巫术，例句同时避免把它泛指民俗。'),M('The historian called the church’s ordinary hymn singing diabolism, although no devil worship was alleged.','The historian called the alleged devil worship diabolism, although ordinary hymn singing was also recorded.','普通赞美诗歌唱不能据此称作 diabolism；术语专指魔鬼崇拜相关信仰/实践。'),[Q('diabolism',1,1,'Diabolism is most directly associated with?','worship of the devil or magic linked to the devil','the study of arithmetic','the ordinary planting of crops','diabolism 指魔鬼崇拜或相关巫术。'),Q('diabolism',2,1,'A medieval accusation of diabolism would concern?','alleged dealings with the devil','a dispute about a tax rate','a lesson in grammar','该词常见于关于魔鬼崇拜的历史语境。'),Q('diabolism',3,1,'Which topic belongs in a study of diabolism?','historical beliefs about devil worship','the anatomy of tree roots','the design of a household radio','魔鬼崇拜信念与实践属于 diabolism 主题。'),Q('diabolism',4,1,'The suffix -ism here marks?','a system or practice of belief','a person who repairs shoes','the past tense of a verb','-ism 常构成信仰、体系或实践名称。')]);
P('diagnosis','diagnosis 借自希腊语 diagnosis“辨别、判断”，由 dia-“通过”与 gignoskein“认识”构成；可指疾病诊断或故障原因判定。',C('diagnosis.s2','设备维修','The technician’s diagnosis was that a loose cable, not a failed battery, caused the intermittent shutdowns.','技术人员判断，间歇性关机是由电缆松动而非电池损坏造成的。','The technician’s diagnosis was that a loose cable / not a failed battery / caused the intermittent shutdowns.','diagnosis 可接 that 从句说明判断内容；主语从句内部 not A but B 对照。','句中判断的是设备故障原因而非疾病，体现 s2。'),M('The diagnosis identified a loose cable as the cause, so the technician replaced the battery without checking the cable.','The diagnosis identified a failed battery as the cause, so the technician replaced the battery.','若诊断明确指出电缆松动，直接换电池与该判断不符；修正诊断结果保持行动合理。'),[Q('diagnosis',1,1,'A doctor’s diagnosis identifies?','the illness a patient has','the patient’s preferred meal','the hospital’s address','医学诊断判定患者患有什么疾病。'),Q('diagnosis',2,2,'An engineer’s diagnosis of a faulty pump states?','what is causing the malfunction','the patient’s blood type','the pump’s retail color','设备诊断用来找到故障原因。'),Q('diagnosis',3,1,'Before choosing a repair, the mechanic needs a?','diagnosis of the engine problem','dictation of a poem','devaluation of the car','维修前要判断发动机出了什么问题。'),Q('diagnosis',4,1,'The plural of diagnosis is?','diagnoses','diagnosises','diagnosis’s','diagnosis 的复数形式是 diagnoses。','spelling')]);
P('diagnostic','diagnostic 来自 diagnosis，加形容词后缀 -ic；作形容词指用于辨识疾病或故障，也可作名词指检测或诊断特征。',C('diagnostic.s2','计算机维护','The laptop’s built-in diagnostic flagged a failing fan and saved the technician from replacing parts at random.','笔记本电脑自带的诊断程序标出了故障风扇，避免技术人员盲目更换零件。','The laptop’s built-in diagnostic flagged a failing fan / and saved the technician / from replacing parts at random.','diagnostic 作可数名词；flag + 问题表示标记出问题。','这里是识别故障的诊断程序，使用名词义 s2。'),M('The diagnostic test was designed to confuse the doctor and provide no information about the illness.','The diagnostic test was designed to help the doctor identify the illness.','诊断测试的用途是识别疾病，不是故意让诊断混乱。'),[Q('diagnostic',1,1,'A diagnostic tool is designed to?','identify a condition or fault','hide every error','increase a currency’s value','形容词 diagnostic 表示用于辨识疾病或故障。'),Q('diagnostic',2,2,'A computer’s diagnostic may be?','a test or program that locates a problem','a person who writes a poem aloud','a building permit','名词 diagnostic 可指诊断测试或程序。'),Q('diagnostic',3,1,'A rash can be diagnostic of a disease when it?','is a feature that helps identify it','is unrelated to any condition','appears only in a textbook drawing','某特征若有助识别疾病，便可能具有诊断意义。'),Q('diagnostic',4,1,'Which phrase is natural?','a diagnostic examination','a diagnostic yesterday','a diagnose examination','diagnostic 是形容词，可修饰 examination。')]);
P('diagonal','diagonal 经法语和拉丁语 diagonalis 借自希腊语 diagōnios“由角到角”；作形容词表示斜向/对角的，也作名词指对角线。',C('diagonal.s2','几何','Draw a diagonal from the rectangle’s upper-left corner to its lower-right corner, then compare the two triangles it creates.','从矩形左上角向右下角画一条对角线，再比较它形成的两个三角形。','Draw a diagonal from the rectangle’s upper-left corner to its lower-right corner / then compare the two triangles it creates.','diagonal 作可数名词；from A to B 描述线段两端。','连接矩形相对角的直线是对角线，符合名词义 s2。'),M('The diagonal joined adjacent corners and ran along the rectangle’s top edge.','The horizontal side joined adjacent corners and ran along the rectangle’s top edge.','沿矩形边连接相邻角的线不是对角线；改称 horizontal side。'),[Q('diagonal',1,2,'A diagonal across a rectangle joins?','opposite corners','the same point twice','only the centers of two adjacent sides','几何名词 diagonal 连接图形的相对角。'),Q('diagonal',2,1,'A diagonal stripe runs?','at a slant across the fabric','straight along a horizontal edge only','in a perfect circle','形容词 diagonal 表示斜向的。'),Q('diagonal',3,2,'How many diagonals does a rectangle have?','two','one','six','矩形两对相对角可连出两条对角线。'),Q('diagonal',4,1,'In a square, a diagonal divides it into?','two triangles','three circles','one pentagon','对角线将正方形分成两个三角形。')]);
P('diagonally','diagonally 由 diagonal 加副词后缀 -ly 构成；diagonal 溯源于希腊语 diagōnios“由角到角”，副词表示沿斜线或对角方向。',C('diagonally.s1','室内布置','Mara placed the rug diagonally across the narrow room, so its corners pointed toward the walls instead of running parallel to them.','玛拉把地毯斜着铺在狭长房间里，使地毯四角朝向墙壁，而非与墙平行。','Mara placed the rug diagonally across the narrow room / so its corners pointed toward the walls / instead of running parallel to them.','diagonally 修饰 placed，说明摆放方向；so 引出结果。','地毯不与墙平行而是斜向摆放，符合副词义。'),M('The arrow crossed the square diagonally while following one side from left to right.','The arrow crossed the square horizontally while following one side from left to right.','沿一条边水平移动不是对角方向；应改为 horizontally。'),[Q('diagonally',1,1,'To cut a sandwich diagonally, cut it?','from one corner toward the opposite corner','straight across the middle in a horizontal line only','into a perfect circle','diagonally 表示沿对角斜线方向。'),Q('diagonally',2,1,'A person moving diagonally across a hall travels?','at a slant between opposite sides','only along the nearest wall','vertically through the floor','斜穿大厅是对角方向移动。'),Q('diagonally',3,1,'Which phrase correctly uses the adverb?','The tiles were laid diagonally.','The tiles were laid diagonal.','The tiles were diagonally tile.','laid 之后用副词 diagonally 表示铺设方向。'),Q('diagonally',4,1,'A diagonal line passes?','obliquely across a shape','only around its outer border','straight up without crossing it','diagonally 描述穿过图形的斜向路径。')]);
P('dialectic','dialectic 源自拉丁语 dialectica、希腊语 dialektikē（与交谈、论辩有关）；作名词指通过对立观点检验思想的论辩方法，也作形容词。',C('dialectic.s1','哲学讨论','In the seminar’s dialectic, students tested the claim that freedom requires rules by setting it against the opposing argument.','在研讨课的辩证论辩中，学生用相反论点检验“自由需要规则”这一主张。','In the seminar’s dialectic / students tested the claim that freedom requires rules / by setting it against the opposing argument.','dialectic 作名词；by + 动名词短语说明采用的方法。','主张与反方论证相互检验，体现辩证论辩方法。'),M('The dialectic ended as soon as everyone repeated the same claim and no opposing view was considered.','The debate ended as soon as everyone repeated the same claim and no opposing view was considered.','不检验对立观点的单一重复不是 dialectic 所指的论辩方法。'),[Q('dialectic',1,1,'A dialectic tests ideas by?','confronting them with opposing arguments','repeating them without discussion','measuring their length','辩证法通过相反观点检验主张。'),Q('dialectic',2,2,'A dialectic question asks whether an argument is?','concerned with this method of opposing ideas','written in a foreign alphabet','about a city’s diagonal streets','形容词 dialectic 指与辩证论辩方法有关。'),Q('dialectic',3,1,'Which classroom activity is dialectical?','students challenge a thesis with a counterargument','students copy a definition silently','students count chairs in the room','提出反论来检验论点，是辩证讨论。'),Q('dialectic',4,1,'In philosophy, dialectic is closest to?','reasoning through opposing positions','unquestioning memorization','a test of physical strength','dialectic 是通过论辩推进思想的方法。')]);
P('diametrically','diametrically 由 diametric 加 -ally 构成；diametric 经拉丁语、希腊语与 diameter（穿过圆心的直径）同源，常用来强调两端截然相反。',C('diametrically.s1','意见分歧','The two candidates were diametrically opposed on housing: one wanted strict rent controls, while the other wanted them abolished.','两位候选人在住房问题上截然对立：一人主张严格租金管制，另一人则主张废除。','The two candidates were diametrically opposed on housing / one wanted strict rent controls / while the other wanted them abolished.','固定搭配 diametrically opposed；while 对照双方主张。','双方立场完全相反，符合“截然相反地”。'),M('Their views were diametrically similar, with both candidates proposing the same policy.','Their views were nearly identical, with both candidates proposing the same policy.','提出同一政策表示相似而非截然相反；应改为 nearly identical。'),[Q('diametrically',1,1,'Diametrically opposed views are?','complete opposites','almost identical','equally uncertain','该副词常加强“截然相反”。'),Q('diametrically',2,1,'The word is commonly paired with which adjective?','opposed','hungry','wooden','固定搭配是 diametrically opposed。'),Q('diametrically',3,1,'Two policies that cannot both be true may be?','diametrically opposed','carefully measured','temporarily postponed','互不相容、完全相反的政策属于 diametrically opposed。'),Q('diametrically',4,1,'If two accounts differ diametrically, they?','contradict each other at fundamental points','contain the same details','are written in the same handwriting','diametrically 表示在根本点上相反。')]);
P('diarrhea','diarrhea 经拉丁语 diarrhoea 源于希腊语 diarrhoia，含“流经、倾泻”之意；是消化道症状名词，英式拼法常作 diarrhoea。',C('diarrhea.s1','健康照护','Because the child had diarrhea and could not keep fluids down, the nurse advised the parents to seek medical care that afternoon.','孩子腹泻且无法留住补液，护士建议父母当天下午就医。','Because the child had diarrhea / and could not keep fluids down / the nurse advised the parents to seek medical care that afternoon.','diarrhea 通常作不可数名词；because 引导原因。','反复稀便并伴随无法补液，属于腹泻语境。'),M('The patient had diarrhea, so her stools were unusually hard and infrequent.','The patient had constipation, so her stools were unusually hard and infrequent.','硬且稀少的排便是便秘表现，与 diarrhea 相反。'),[Q('diarrhea',1,1,'Diarrhea is characterized by?','repeated loose or watery stools','a broken arm','a persistent inability to hear','该症状指反复稀便或水样便。'),Q('diarrhea',2,1,'Which action is sensible during severe diarrhea?','replace fluids and seek medical advice if needed','avoid all fluids indefinitely','share unwashed utensils','腹泻可能造成脱水，需要补液并视情况求医。'),Q('diarrhea',3,1,'Which spelling is common in British English?','diarrhoea','diarreah','diarrhia','英式拼写常见 diarrhoea。','spelling'),Q('diarrhea',4,1,'The closest opposite condition is?','constipation','fever','a rash','便秘与腹泻的排便表现相反。')]);
P('dichotomy','dichotomy 源自希腊语 dichotomia，由 dicha“分成两部分”与 temnein“切”构成，指把事物分为两个互斥类别或观念。',C('dichotomy.s1','论证分析','The report rejected the dichotomy between work and family, noting that many people care for relatives while holding a job.','报告否定了工作与家庭之间的二分对立，并指出许多人一边工作一边照护亲属。','The report rejected the dichotomy between work and family / noting that many people care for relatives / while holding a job.','dichotomy between A and B 表示 A、B 间的二分；reject 后接名词。','报告指出两类并非互斥，讨论的正是二分法。'),M('The dichotomy divided the issue into four mutually exclusive categories.','The classification divided the issue into four mutually exclusive categories.','dichotomy 是二分；分成四类不符合该词的核心构词和定义。'),[Q('dichotomy',1,1,'A dichotomy divides an issue into?','two contrasting or exclusive parts','four equal parts','no categories at all','dichotomy 指两分法或二元对立。'),Q('dichotomy',2,1,'An apparent dichotomy between city and country suggests?','the two are presented as opposing categories','there is only one location','the words have identical meanings','dichotomy 把对象呈现为相对的两类。'),Q('dichotomy',3,1,'Which phrase is standard?','a dichotomy between theory and practice','a dichotomy among five colours','a dichotomy with no division','常用结构为 dichotomy between A and B。'),Q('dichotomy',4,1,'A writer questions a false dichotomy when?','the supposed two choices are not the only possibilities','the evidence supports exactly two choices','the writer counts two pages','质疑虚假二分即指出选择不只限于被设定的两类。')]);
P('dictaphone','Dictaphone 原为商标名，后来常用作普通名词，指把口述内容录下供稍后转写的录音机；词形与 dictate、phone 相关。',C('dictaphone.s1','办公室工作','The solicitor recorded the client’s notes on a dictaphone during the meeting, then sent the audio file to an assistant for transcription.','会谈期间律师把客户的笔记口述录进口授录音机，随后将音频文件交给助理转写。','The solicitor recorded the client’s notes on a dictaphone during the meeting / then sent the audio file / to an assistant for transcription.','record on a dictaphone 表示录在口述录音设备上；for transcription 表目的。','设备录下口述内容，供稍后打字转写，符合词条义。'),M('She typed her spoken notes into the dictaphone, which printed them without recording sound.','She recorded her spoken notes on the dictaphone, then had them typed up.','dictaphone 录音而非直接打印文字；将输入方式改为录音即可。'),[Q('dictaphone',1,1,'A dictaphone is primarily used to?','record speech for later transcription','measure room temperature','print photographs','口述内容录下后可供转写。'),Q('dictaphone',2,1,'Who might make use of a dictaphone at work?','a lawyer dictating a letter','a baker measuring flour','a pilot reading a compass','律师可口述信件供助理转写。'),Q('dictaphone',3,1,'After recording on a dictaphone, an assistant may?','transcribe the spoken words','develop a film negative','repair a bicycle tyre','录音下一步通常是将话语转成文字。'),Q('dictaphone',4,1,'Which action best matches the device?','speaking a report into a recorder','scanning a printed map','projecting a silent slide','dictaphone 的核心功能是录制口述。')]);
P('dictation','dictation 来自拉丁语 dictare“反复说、口授”，经法语进入英语；可指口授供记录，也指课堂听写，亦可指强制命令。',C('dictation.s2','政治评论','The editor complained that the new rules were imposed by ministerial dictation, leaving local councils no room to adapt them.','编辑抱怨新规是部长强行下令制定的，使地方议会毫无调整余地。','The editor complained that the new rules were imposed by ministerial dictation / leaving local councils no room / to adapt them.','dictation 作不可数名词；by ministerial dictation 指部长的命令支配。','中央强行命令地方执行，符合“命令、支配”义 s2。'),M('The pupils took dictation by listening carefully and memorizing each word without writing it down.','The pupils took dictation by writing each word as they heard it.','课堂 dictation 是把听到的话写下来；只记在脑中而不落笔没有完成听写。'),[Q('dictation',1,1,'In class, dictation is an exercise where pupils?','write down words they hear','draw objects they see','solve sums they smell','课堂听写要求把听到的词写下来。'),Q('dictation',2,2,'Government by dictation suggests decisions are?','imposed as orders with little room for choice','made by open local discussion','left entirely to chance','抽象义 dictation 指命令式支配。'),Q('dictation',3,1,'A manager dictates a note so a colleague can?','write down the spoken words','translate a map into a graph','repair a recording device','口述供记录是 dictation 的基本用法。'),Q('dictation',4,1,'Which verb naturally collocates with a school dictation?','do','manufacture','breathe','学生常 do/complete a dictation。')]);
P('dictator','dictator 经拉丁语 dictator 借自 dictare“命令、口授”；古罗马曾是有任期的官职，现代多指不受制约的专制统治者。',C('dictator.s1','政治制度','The dictator dissolved parliament, banned rival parties, and ruled by decree for more than a decade.','独裁者解散议会、禁止竞争政党，并靠法令统治了十多年。','The dictator dissolved parliament / banned rival parties / and ruled by decree for more than a decade.','dictator 作可数名词；三个并列过去式动词概述其行事。','独掌权力、压制政党并以法令统治，体现现代常见义。'),M('The dictator welcomed free elections, accepted defeat, and transferred power peacefully.','The elected leader welcomed free elections, accepted defeat, and transferred power peacefully.','接受选举结果并和平交权与现代 dictator 的专制统治特征不符。'),[Q('dictator',1,1,'A modern political dictator usually?','holds power without meaningful limits','serves only as an elected ceremonial host','has no authority over government','dictator 通常指掌握专制权力的统治者。'),Q('dictator',2,1,'Which action is most characteristic of a dictator?','banning opposition parties','inviting rivals to share equal power','leaving every decision to a referendum','压制反对党是独裁统治的典型做法。'),Q('dictator',3,1,'In ancient Rome, a dictator was historically?','an appointed magistrate with extraordinary authority for a set period','a household servant','a poet chosen by lottery','古罗马 dictator 原是拥有特别权力的官职。'),Q('dictator',4,1,'A dictator differs from a pluralistic elected leader because the dictator?','concentrates authority and restricts opposition','always follows a strict two-term limit','cannot issue any orders','现代义侧重权力集中与压制反对。')]);
P('dictatorial','dictatorial 由 dictator + -ial 构成，指独裁统治者相关的，或专断地发号施令、不容讨论的。',C('dictatorial.s2','工作沟通','The supervisor’s dictatorial tone discouraged questions; she announced every shift change as a command and rejected requests for discussion.','主管专断的语气让人不敢提问；她把每次换班都当作命令宣布，并拒绝讨论请求。','The supervisor’s dictatorial tone discouraged questions / she announced every shift change as a command / and rejected requests for discussion.','dictatorial 修饰 tone；discourage + 名词表示使人不敢做某事。','不容提问、把安排当命令，体现日常行为中的专断义 s2。'),M('The manager was dictatorial because she invited staff to debate every option and changed her mind after hearing them.','The manager was consultative because she invited staff to debate every option and changed her mind after hearing them.','鼓励讨论并听取意见是协商式管理，与 dictatorial 的专断不符。'),[Q('dictatorial',1,1,'A dictatorial government is?','ruled with concentrated, unchecked power','run by freely elected local clubs only','without any authority structure','dictatorial 可形容独裁统治。'),Q('dictatorial',2,2,'A dictatorial manager tends to?','issue orders without allowing discussion','invite debate and share decisions','avoid directing any work','专断的管理者不容讨论、只发命令。'),Q('dictatorial',3,1,'Which tone sounds dictatorial?','“Do it now; questions are not permitted.”','“Let’s compare the options together.”','“Please suggest a better approach.”','不准提问的命令语气很专断。'),Q('dictatorial',4,1,'Dictatorial is formed from which noun?','dictator','dictionary','dictation only','形容词 dictatorial 来自 dictator。')]);
P('dictatorship','dictatorship 由 dictator + -ship 构成，后缀表示身份、状态或体制；可指独裁政权，也指独裁者的任期或职位。',C('dictatorship.s2','历史叙述','During her dictatorship, the ruler censored newspapers and imprisoned opponents, but she was eventually removed from office.','在她的独裁统治期间，统治者审查报纸并监禁反对者，但最终还是被赶下台。','During her dictatorship / the ruler censored newspapers and imprisoned opponents / but she was eventually removed from office.','during + 名词表示在某段统治期间；but 表示转折。','句中指统治者掌权的职位和时期，是 s2。'),M('The dictatorship shared authority through competitive elections and had no single ruler.','The parliamentary system shared authority through competitive elections and had no single ruler.','分权竞争的议会制度不等于由独裁者统治的 dictatorship。'),[Q('dictatorship',1,1,'A country under dictatorship is generally governed by?','a ruler or ruling group with unchecked power','a monarch whose authority is only ceremonial','citizens directly making every decision','dictatorship 是独裁统治体制。'),Q('dictatorship',2,2,'“During his dictatorship” refers to?','the period when he held dictatorial rule','the day he first learned to read','the years before he entered politics','s2 可指独裁者的执政时期。'),Q('dictatorship',3,1,'Censorship and jailing political opponents are often signs of?','dictatorship','a free press system','a neutral census','压制媒体和反对派常见于独裁政权。'),Q('dictatorship',4,1,'The suffix -ship in dictatorship helps form a word for?','a state, office, or system','a small animal','a direction of travel','-ship 表示身份、状态或体制。')]);
P('diction','diction 经法语 diction 源于拉丁语 dictio“说话、措辞”，可指选词方式，也可指清晰准确的发音。',C('diction.s2','演讲训练','The actor’s diction improved after she practised the final consonants, making every line easy for the back row to hear.','演员练习词尾辅音后吐字更清晰，后排也能听清每句台词。','The actor’s diction improved after she practised the final consonants / making every line easy / for the back row to hear.','diction 作不可数名词；making 结构说明改进后的结果。','练习辅音让语音更清晰，体现发音、吐字义 s2。'),M('The speaker’s diction was clear because every word was muffled and impossible to distinguish.','The speaker’s diction was unclear because every word was muffled and impossible to distinguish.','难以分辨的含混发音表示 diction 不清晰，而不是 clear。'),[Q('diction',1,1,'A writer’s diction is the?','choice and use of words','length of the paper','colour of the ink','写作 diction 指选词和用词方式。'),Q('diction',2,2,'An actor practises diction to improve?','pronunciation and clarity of speech','handwriting on a script','memory of stage directions','表演语境中的 diction 指发音清晰度。'),Q('diction',3,1,'A poem with formal diction uses?','deliberately chosen elevated or formal words','only random sounds','no words at all','语域与词语选择体现 diction。'),Q('diction',4,1,'If an audience cannot distinguish a speaker’s consonants, the problem is?','poor diction','a larger vocabulary','a plot twist','发音含混是 diction 不佳。')]);
P('dictum','dictum 来自拉丁语 dictum“所说的话”，是 dicere“说”的过去分词形式；指被当作一般真理的简短格言或断语。',C('dictum.s1','管理原则','The old coach repeated the dictum “practice beats talent without discipline” whenever the team grew complacent.','球队一旦自满，老教练就反复讲“缺乏自律的天赋不如训练”的格言。','The old coach repeated the dictum “practice beats talent without discipline” / whenever the team grew complacent.','dictum 作可数名词；引号内为格言内容，whenever 引出每当某情形。','句子是被反复引用、作为普遍道理的简短断语。'),M('The dictum was a long list of unrelated data with no claim or general lesson.','The report was a long list of unrelated data with no claim or general lesson.','dictum 是简短断语，不是冗长且没有观点的数据清单。'),[Q('dictum',1,1,'A dictum is usually?','a concise statement offered as a general truth','a detailed map of a coastline','an unspoken question','dictum 是简短的格言或断语。'),Q('dictum',2,1,'Which could be called a dictum?','“Measure twice, cut once.”','a 300-page phone directory','a list of unlabeled numbers','这句简短经验之谈属于格言。'),Q('dictum',3,1,'A writer cites an old dictum to?','invoke a familiar guiding principle','show a chemical reaction','record a person’s height','引用 dictum 是援引一个常见准则。'),Q('dictum',4,1,'The plural of dictum is?','dicta','dictumses','dictumes','拉丁来源名词 dictum 的常见复数是 dicta。','plural')]);
P('didactic','didactic 源自希腊语 didaktikos“善于教导的”，与 didaskein“教”相关；既可指教学的，也常带贬义指过分说教。',C('didactic.s1','文学评论','The novel’s ending felt didactic because every character stopped acting naturally so the narrator could spell out the moral.','这部小说的结尾显得说教味太重，因为每个人物都不再自然行动，只为让叙述者直白讲出道理。','The novel’s ending felt didactic / because every character stopped acting naturally / so the narrator could spell out the moral.','didactic 作表语形容词；because 解释读者感受的原因。','道德教训被过分直白地讲出，符合带贬义的 s1。'),M('The story was didactic in the sense that it avoided teaching anything and had no instructional purpose.','The story was entertaining rather than didactic because it avoided teaching anything.','没有教学或道德劝诫目的的故事不属于 didactic。'),[Q('didactic',1,1,'A didactic novel may seem annoying because it?','pushes a moral lesson too directly','contains no language','is written without characters','带贬义的 didactic 指过分迫切地教训读者。'),Q('didactic',2,2,'A didactic guide is intended to?','teach or instruct','hide all information','entertain without any instruction','中性义 didactic 表示旨在教学。'),Q('didactic',3,1,'Which line sounds most didactic?','“You must learn this lesson,” the narrator explains after every event.','The rain tapped softly against the empty window.','She opened the letter and read it twice.','频繁直白训诫呈现说教感。'),Q('didactic',4,1,'Didactic ultimately relates to the idea of?','teaching','digging','measuring','词源与希腊语“教”有关。')]);
P('dietary','dietary 由 diet 加 -ary 构成，diet 经法语、拉丁语来自希腊语 diaita“生活方式、饮食”；表示与食物摄取或规定饮食有关。',C('dietary.s2','医疗营养','The clinic prepared a low-sodium dietary plan that set daily limits and listed suitable alternatives for canned foods.','诊所制定了一份低钠饮食方案，设定每日限量，并列出罐头食品的合适替代品。','The clinic prepared a low-sodium dietary plan / that set daily limits / and listed suitable alternatives for canned foods.','dietary 修饰 plan；that 引导定语从句说明计划内容。','方案规定每日可摄入的食物，体现“规定的食物/饮食”义 s2。'),M('Her dietary plan prohibited salt but recommended adding as much sodium as possible.','Her dietary plan limited salt and recommended lower-sodium alternatives.','限钠方案不可能同时建议尽可能摄入钠；修正后保持原意一致。'),[Q('dietary',1,1,'Dietary advice concerns?','what a person eats','how a person repairs a roof','which road a bus takes','dietary 指与饮食摄取有关。'),Q('dietary',2,2,'A prescribed dietary allowance is?','a regulated amount or selection of food','a gym membership fee','a medical instrument','dietary 也可指规定的饮食配给。'),Q('dietary',3,1,'A dietary restriction for an allergy may require someone to?','avoid the food that triggers a reaction','eat only foods that contain the allergen','stop drinking water','过敏饮食限制要求避开致敏食物。'),Q('dietary',4,1,'Which phrase is natural?','dietary requirements','dietary yesterday','dietary to a chair','dietary 可修饰 requirements，表示饮食要求。')]);
P('dieter','dieter 由 diet + -er 构成；diet 源自希腊语 diaita“生活方式”，现代常指为了减轻体重而限制饮食的人。',C('dieter.s1','健康管理','The dieter planned balanced meals with a nutritionist rather than skipping breakfast, hoping to lose weight gradually and safely.','这位节食者与营养师计划均衡膳食，而不是不吃早餐，希望循序渐进且安全地减重。','The dieter planned balanced meals with a nutritionist / rather than skipping breakfast / hoping to lose weight gradually and safely.','dieter 是可数名词；rather than 后可接动名词。','为减重而限制饮食的人符合 dieter 义。'),M('A dieter trying to reduce calories deliberately added extra sugar and stopped tracking food.','A dieter trying to reduce calories chose smaller portions and tracked food.','增加糖分与减热量目标相悖；修正后行动与节食目标相符。'),[Q('dieter',1,1,'A dieter is someone who?','limits food intake, often to lose weight','eats only for a living as a chef','studies the geography of farms','dieter 指节食者，通常为了减重。'),Q('dieter',2,1,'Which person is clearly a dieter?','someone carefully reducing portions to lose weight','someone serving meals at a restaurant','someone writing a restaurant review','有意识控制饮食以减重的人是 dieter。'),Q('dieter',3,1,'The suffix -er in dieter refers to?','a person who follows a diet','a past-tense action','a kind of food container','-er 指采取某种行为的人。'),Q('dieter',4,1,'A dieter’s plan should ideally be?','balanced and safe','based on dehydration','without any nutrients','减重饮食应安全、均衡。')]);
P('dietitian','dietitian 由 diet + -itian 构成，后缀常见于专业从业者名称；指受过资质训练、提供营养和膳食建议的专业人员。',C('dietitian.s1','临床营养','The dietitian reviewed the patient’s blood tests and designed a meal plan that met her needs during kidney treatment.','营养师查看了患者的血液检查结果，并制定了适合其肾脏治疗期间需要的膳食方案。','The dietitian reviewed the patient’s blood tests / and designed a meal plan / that met her needs during kidney treatment.','dietitian 指营养专业人员；that 引导定语从句修饰 meal plan。','根据临床需要提供膳食建议是 dietitian 的专业工作。'),M('The dietitian prescribed antibiotics to treat an infection, although she had no medical prescribing role.','The physician prescribed antibiotics to treat an infection, while the dietitian advised on nutrition.','抗生素处方属于有处方资格的医生职责；营养师提供营养建议。'),[Q('dietitian',1,1,'A dietitian specializes in?','food, nutrition, and dietary advice','designing bridges','repairing recording equipment','营养师的专业领域是食物和营养。'),Q('dietitian',2,1,'Someone with diabetes may consult a dietitian to?','plan meals that support health needs','choose a political party','learn how to operate a dictaphone','营养师可帮助规划适合疾病需求的膳食。'),Q('dietitian',3,1,'Which professional is most likely to assess a meal plan?','a dietitian','a dictator','a dialectic','dietitian 是营养膳食专业人员。'),Q('dietitian',4,1,'A dietitian’s advice is based chiefly on?','nutrition knowledge and a client’s needs','the client’s favourite colour','a random menu generator','营养建议需结合营养知识和个体需求。')]);
P('differential','differential 由 differ + -ential 构成，源于拉丁语 differentia“区别”；可指有差别的、微分的，名词还指工资或利率等差额。',C('differential.s2','薪酬制度','The night-shift differential added three dollars an hour to the base wage, compensating staff for working outside daytime hours.','夜班津贴在基本工资上每小时增加三美元，以补偿员工在日间以外时段工作。','The night-shift differential added three dollars an hour to the base wage / compensating staff / for working outside daytime hours.','differential 作名词修饰 night-shift；add an amount to 表示加到……上。','夜班与日班工资之间的额外差额正是 s2。'),M('The wage differential was zero, so night workers earned three dollars more per hour.','The wage differential was three dollars an hour, so night workers earned more.','若差额为零，两班工资相等，不可能一方多拿三美元。'),[Q('differential',1,1,'Differential treatment gives?','different groups different conditions','every group exactly the same treatment','no one any treatment','形容词 differential 指差异性的。'),Q('differential',2,2,'A wage differential is?','a difference in pay between groups or shifts','the total number of workers','a fixed clock time','名词 differential 指工资之间的差额。'),Q('differential',3,1,'In mathematics, differential calculus studies?','rates of change','the spelling of nouns','historical place names','微分学研究变化率。'),Q('differential',4,1,'If night staff receive a differential, they?','get an extra amount compared with the base rate','must work without pay','receive identical pay by definition','津贴差额使夜班工资高于基本工资。')]);
P('diffusely','diffusely 由 diffuse + -ly 构成；diffuse 源自拉丁语 diffundere“向外倾注、散开”，副词可表示分散地，也可表示表达冗长散漫。',C('diffusely.s2','写作反馈','The reviewer said the essay argued diffusely, circling around the claim for several pages before stating its evidence.','审稿人说这篇文章论述散漫，绕着主张讲了好几页才提出证据。','The reviewer said the essay argued diffusely / circling around the claim for several pages / before stating its evidence.','diffusely 修饰 argued，说明论述方式；before 引导时间关系。','观点铺陈冗长、没有紧扣中心，体现 s2。'),M('The proposal was diffusely concise: it stated the request in one clear sentence.','The proposal was concise: it stated the request in one clear sentence.','一句清楚表达说明简洁，不是冗长散漫；删去自相矛盾的 diffusely。'),[Q('diffusely',1,1,'Light spread diffusely is distributed?','over a broad area rather than a single point','only in one narrow beam','inside a sealed box only','空间义 diffusely 指分散到较广范围。'),Q('diffusely',2,2,'A person who writes diffusely tends to?','use many words without a clear focus','state the point briefly','write only in bullet-free numbers','表达义指冗长而缺乏重点。'),Q('diffusely',3,1,'Which edit would make a diffusely written paragraph clearer?','remove digressions and state the main claim early','add three unrelated anecdotes','repeat each sentence twice','删掉离题内容可减少散漫。'),Q('diffusely',4,1,'The suffix -ly in diffusely marks it as?','an adverb modifying how something spreads or is expressed','a plural noun','a comparative adjective','-ly 构成副词，修饰动作或表达方式。')]);
P('diffusion','diffusion 来自拉丁语 diffusio，源于 diffundere“向外散开”；科学中指粒子由高浓度区域向低浓度区域的净扩散，也泛指传播。',C('diffusion.s1','生物学','Diffusion carries oxygen from the air sacs into nearby blood because the gas is more concentrated in the lungs than in the blood.','氧气从肺泡扩散到附近血液，因为肺部气体浓度高于血液。','Diffusion carries oxygen from the air sacs into nearby blood / because the gas is more concentrated in the lungs than in the blood.','diffusion 作不可数名词；because 引出浓度梯度这一原因。','氧分子沿浓度差扩散，符合科学义。'),M('Diffusion moved the dye from its high-concentration region toward an even higher concentration.','Diffusion moved the dye from its high-concentration region toward a lower concentration.','净扩散方向通常由高浓度到低浓度，而不是向更高浓度处。'),[Q('diffusion',1,1,'Diffusion is the spreading of particles?','from a region of higher concentration toward lower concentration','only from cold objects to hot objects','without any particle movement','扩散的净方向是由高浓度向低浓度。'),Q('diffusion',2,1,'When perfume spreads across a room, the process illustrates?','diffusion','dictation','devaluation','香味分子逐渐散开，体现扩散。'),Q('diffusion',3,1,'In biology, oxygen enters blood partly by?','diffusion across nearby surfaces','a process of word dictation','a currency exchange','氧气可沿浓度梯度扩散进入血液。'),Q('diffusion',4,1,'The diffusion of an idea means its?','gradual spread among people','immediate disappearance from memory','conversion into a chemical element','比喻义 diffusion 可指思想传播。')]);
P('diffusive','diffusive 由 diffuse + -ive 构成；diffuse 源自拉丁语 diffundere“散开、倾注”，形容能使粒子、光或影响向外扩散的，亦可指文字散漫。',C('diffusive.s2','编辑评价','The editor cut the report’s diffusive opening, where three paragraphs repeated the same background before the main finding appeared.','编辑删掉了报告冗长散漫的开头部分，因为主要发现出现前有三段都在重复背景。','The editor cut the report’s diffusive opening / where three paragraphs repeated the same background / before the main finding appeared.','diffusive 修饰 opening；where 引导对开头部分的补充说明。','重复铺垫且缺乏紧凑度对应文字散漫义 s2。'),M('The diffusive paragraph stated the result once in a single precise sentence.','The concise paragraph stated the result once in a single precise sentence.','单句准确表达很紧凑，不符合 diffusive 的冗长散漫义。'),[Q('diffusive',1,1,'A diffusive material tends to?','let particles or energy spread outward','prevent all movement','turn into a single solid point','diffusive 表示具有向外扩散的倾向。'),Q('diffusive',2,2,'A diffusive writing style is?','wordy and not tightly focused','brief and sharply organized','written without any words','文字义指冗长、松散。'),Q('diffusive',3,1,'Which substance might be described as diffusive in a porous surface?','one that spreads through it','one that remains fixed in one spot','one that cannot interact with it','可在多孔表面中扩散的物质有 diffusive 特性。'),Q('diffusive',4,1,'A reviewer asks for a tighter argument after reading a diffusive essay. The writer should?','remove repeated background and digressions','add more unrelated examples','hide the central claim','删去重复和离题内容可使文章紧凑。')]);
P('difluoride','difluoride 是无机化学组合名称，由 di-“二”与 fluoride“氟化物”构成，指每个化学式单位含两个氟原子的化合物类别。',C('difluoride.s1','无机化学','In magnesium difluoride, each magnesium atom is paired with two fluoride ions, giving the formula MgF₂.','在氟化镁中，每个镁原子与两个氟离子配对，化学式为 MgF₂。','In magnesium difluoride / each magnesium atom is paired with two fluoride ions / giving the formula MgF₂.','difluoride 作化合物名称；giving 短语说明其化学式。','名称与化学式都显示两个氟原子/离子对应一个镁，符合定义。'),M('The compound was called a difluoride even though its formula contained three fluorine atoms per central atom.','The compound was called a trifluoride because its formula contained three fluorine atoms per central atom.','前缀 di- 表示二；每个中心原子有三个氟应称 trifluoride。'),[Q('difluoride',1,1,'The prefix di- in difluoride indicates?','two fluorine atoms','one oxygen atom','four carbon atoms','di- 表示二，因此 difluoride 含两个氟。'),Q('difluoride',2,1,'A compound named difluoride contains how many fluorine atoms per formula unit?','two','one','six','difluoride 的名称明确给出两个氟原子。'),Q('difluoride',3,1,'MgF₂ is magnesium?','difluoride','monofluoride','trifluoride','MgF₂ 每个镁对应两个氟，称氟化镁。'),Q('difluoride',4,1,'Which prefix would fit a compound with three fluorides?','tri-','di-','mono-','三个用 tri-，而 di- 指两个。')]);
P('digestible','digestible 由 digest + -ible 构成，digest 经拉丁语 digerere“分开、消化”；可指身体容易消化，也可指信息易懂。',C('digestible.s2','科普写作','The science writer broke the findings into short sections so the report would be digestible for readers with no technical background.','科普作者把研究结果分成短小部分，让没有专业背景的读者也能轻松理解报告。','The science writer broke the findings into short sections / so the report would be digestible / for readers with no technical background.','digestible 作表语形容词；so 引导目的/结果从句。','清楚分段使信息易懂，体现比喻义 s2。'),M('The guide was digestible to beginners because every sentence was packed with unexplained specialist jargon.','The guide was incomprehensible to beginners because every sentence was packed with unexplained specialist jargon.','大量未解释的专业术语会使文本难懂，而不是 digestible。'),[Q('digestible',1,1,'Food described as digestible is?','able to be broken down by the body','impossible to chew or process','already turned into a written report','生理义指能够被身体消化。'),Q('digestible',2,2,'A digestible summary is?','easy for readers to understand','too technical for anyone to follow','a meal that must be swallowed whole','信息义 digestible 指容易理解。'),Q('digestible',3,1,'Which meal is most likely to be digestible for someone recovering from illness?','a simple, light meal recommended by a clinician','a huge portion of very greasy food','a plate of inedible stones','清淡且适合康复者的食物通常较易消化。'),Q('digestible',4,2,'A teacher makes a complex topic digestible by?','explaining it in clear, manageable steps','adding unexplained jargon','removing all examples and definitions','分步清楚讲解让知识更易理解。')]);
P('digestive','digestive 由 digest + -ive 构成；digest 源自拉丁语 digerere“分开、消化”，形容与消化过程有关，也可作名词指助消化的食物或药。',C('digestive.s2','餐后饮食','After dinner, the host served small digestive biscuits with tea, a customary sweet snack rather than a medical treatment.','晚餐后，主人端上茶和小块消化饼干，这是一种常见甜点，而非药物治疗。','After dinner / the host served small digestive biscuits with tea / a customary sweet snack rather than a medical treatment.','digestive 在此为名词用作定语，组成 biscuit 名称；rather than 表示而非。','digestive biscuit 是助消化饼干这一食品名，属 s2 名词用法。'),M('The digestive biscuits were prescribed as antibiotics to kill bacteria in the bloodstream.','The digestive biscuits were served as a snack after the meal.','digestive biscuit 是饼干，并非抗生素处方药；更正为餐后点心语境。'),[Q('digestive',1,1,'The digestive system is concerned with?','breaking down food and absorbing nutrients','producing sound waves','moving a planet around a star','digestive 形容与消化过程有关。'),Q('digestive',2,2,'In British usage, a digestive may be?','a biscuit eaten after a meal','a kind of blood test only','a medical specialist who performs surgery','名词 digestive 可指消化饼干。'),Q('digestive',3,1,'Which phrase names an organ system?','the digestive tract','the dictatorial tract','the diagonal tract','digestive tract 是消化道。'),Q('digestive',4,1,'A digestive enzyme helps?','break food into substances the body can process','raise the price of food','record spoken instructions','消化酶帮助分解食物。')]);
P('dignified','dignified 是 dignify 的过去分词形容词；dignify 源于拉丁语 dignus“值得的”，可指举止庄重有尊严，也可指高尚。',C('dignified.s1','公共场合','Despite the hostile questions, the witness gave a dignified reply and refused to insult anyone in the courtroom.','尽管问题带有敌意，证人仍作出庄重得体的回答，没有侮辱法庭上的任何人。','Despite the hostile questions / the witness gave a dignified reply / and refused to insult anyone in the courtroom.','dignified 修饰 reply；despite 后接名词短语表示让步。','冷静、庄重、不失尊严的回应符合 s1。'),M('The dignified guest shouted insults, threw food, and mocked everyone at the memorial.','The unruly guest shouted insults, threw food, and mocked everyone at the memorial.','在追悼会上叫嚷侮辱他人并非庄重得体；unruly 符合失序行为。'),[Q('dignified',1,1,'A dignified manner is?','calm and deserving of respect','rude and deliberately humiliating','careless and childish','dignified 指庄重、值得尊敬的举止。'),Q('dignified',2,2,'A dignified action may show?','high moral worth','a small physical size','a lack of any opinion','dignified 也可指高尚有品格。'),Q('dignified',3,1,'Which response is dignified after a provocation?','answering firmly without personal insults','throwing objects at the speaker','spreading a false rumor','克制而坚定地回应保持尊严。'),Q('dignified',4,1,'A dignified ceremony is likely to be?','serious and respectful','chaotic and mocking','designed to confuse guests','庄重的仪式氛围严肃而尊重。')]);
P('dignify','dignify 来自拉丁语 dignus“值得的”及英语动词后缀 -ify，意为赋予尊严/重要性，也可讽刺地表示抬举不值得尊重之物。',C('dignify.s2','审慎表达','The spokesperson refused to dignify the baseless rumor with a response, saying the team would focus on verified facts instead.','发言人拒绝回应这条毫无根据的谣言，表示团队会转而专注于已核实的事实。','The spokesperson refused to dignify the baseless rumor with a response / saying the team would focus on verified facts instead.','dignify A with B 可指以 B 抬举/回应 A；refuse to 后接动词原形。','固定表达“不给谣言以回应”，体现不愿抬举不值一提之事的 s2。'),M('The speaker dignified the silly rumor by treating it as a serious verified fact and citing it as proof.','The speaker did not dignify the silly rumor with a response, treating it as unworthy of attention.','此处 intended meaning 是拒绝认真对待谣言；原句反而将它抬举成证据。'),[Q('dignify',1,1,'To dignify a person is to?','give that person honour or importance','remove every title from the person','make the person physically taller','dignify 的基本义是赋予尊严或重要性。'),Q('dignify',2,2,'“I will not dignify that insult with a reply” means?','I will not treat the insult as worthy of an answer','I will praise the insult','I will repeat it word for word','s2 常用于拒绝抬举不值得认真对待之事。'),Q('dignify',3,1,'Which sentence uses dignify positively?','The award dignified the years of quiet public service.','The award made the service physically taller.','The award erased every record of the service.','奖项赋予长期服务以尊荣。'),Q('dignify',4,1,'Dignify is closest in meaning to?','honour','disfigure','dilute','dignify 表示使显得有尊严或重要。')]);
P('digress','digress 经拉丁语 digredi“走离、偏离”进入英语，含 dis-/di-“离开”与 gradi“走”；指谈话或写作偏离主题。',C('digress.s1','会议发言','I will digress for a moment to explain how the sample was collected, then return to the main results.','我先暂时离题说明样本是如何采集的，然后回到主要结果。','I will digress for a moment / to explain how the sample was collected / then return to the main results.','digress 常用不及物结构；return to the main results 标明回归主题。','发言者短暂离开主要结果再返回，符合离题义。'),M('The chair asked the speaker to digress from the topic and remain exactly on the agenda throughout.','The chair asked the speaker not to digress from the topic and to remain on the agenda throughout.','保持议程即要求不要偏离主题；原句前后指令矛盾。'),[Q('digress',1,1,'A speaker who digresses?','moves away from the main subject','states the main point and stops','reads the same sentence twice','digress 指偏离正在讨论的主题。'),Q('digress',2,2,'A writer digresses into a side topic when the writer?','leaves the central argument briefly','summarizes the central claim exactly','corrects a spelling error','写作中的 digress 是转向枝节话题。'),Q('digress',3,1,'Which phrase commonly follows digress?','digress from the point','digress at the ceiling','digress with a ruler','常用搭配是 digress from a subject/point。'),Q('digress',4,1,'“I do not wish to digress” signals the speaker wants to?','stay focused on the subject','change the topic immediately','end all communication','这句话表示不想离题。')]);
P('dilapidate','dilapidate 经拉丁语 dilapidare“像扔石头般毁坏”进入英语，含 di- 与 lapis“石头”；指因疏于维护而使建筑破败，也可不及物。',C('dilapidate.s1','房屋维护','Years of neglect dilapidated the manor, and rain began entering through gaps in the collapsed roof.','多年无人维护使庄园逐渐破败，雨水开始从坍塌屋顶的缝隙漏入。','Years of neglect dilapidated the manor / and rain began entering / through gaps in the collapsed roof.','dilapidate 作及物动词，宾语是变破败的建筑；years of neglect 是原因。','长期缺乏维护造成建筑损坏，体现动词义。'),M('The owners dilapidated the cottage by repairing the roof and replacing every rotten beam.','The owners restored the cottage by repairing the roof and replacing every rotten beam.','修屋顶、更换腐梁是在修复而非使建筑破败；restored 符合行为。'),[Q('dilapidate',1,1,'To dilapidate a house is to?','let it fall into disrepair','paint it carefully','sell it at auction','dilapidate 指使建筑因失修而破败。'),Q('dilapidate',2,1,'A building may dilapidate after?','years without maintenance','a thorough restoration','a new roof installation','缺少维护会导致建筑逐渐破败。'),Q('dilapidate',3,1,'Which is a likely result of a dilapidated structure?','leaks and crumbling walls','freshly sealed windows','a newly reinforced foundation','失修的建筑常有漏水和墙体破损。'),Q('dilapidate',4,1,'The term is most often used about?','buildings or property','a spoken sentence only','a currency exchange','dilapidate 常描述房屋或建筑失修。')]);
P('dilapidated','dilapidated 是 dilapidate 的过去分词形容词；源于拉丁语 dilapidare，字面与石头散落/毁坏相关，现代指因年久失修而破败。',C('dilapidated.s1','乡村建筑','A dilapidated barn stood beside the road, with missing boards, a sagging roof, and weeds growing through the floor.','路边立着一间破败谷仓，木板缺失、屋顶下陷，杂草从地板缝里长出。','A dilapidated barn stood beside the road / with missing boards, a sagging roof / and weeds growing through the floor.','dilapidated 修饰 barn；with 短语列举破败迹象。','屋顶下陷、木板缺失是失修建筑的具体表现。'),M('The dilapidated school had just been fully renovated and had no damage or maintenance problems.','The renovated school had just been fully repaired and had no damage or maintenance problems.','刚修缮且无损坏的建筑不应称为 dilapidated。'),[Q('dilapidated',1,1,'A dilapidated building is?','old and falling apart from neglect','newly built and spotless','temporarily closed for a holiday','dilapidated 指因失修而破败。'),Q('dilapidated',2,1,'Which detail suggests a house is dilapidated?','a sagging roof and broken window frames','a new roof and fresh paint','a locked door during business hours','屋顶下陷、窗框破损是破败征兆。'),Q('dilapidated',3,1,'A city might demolish a dilapidated building because it?','is unsafe after years of neglect','has too many newly installed lights','was cleaned yesterday','长期失修可能使建筑不安全。'),Q('dilapidated',4,1,'Dilapidated is closest to?','run-down','immaculate','unfinished in a good way','run-down 与破败义相近。')]);
P('dilate','dilate 源自拉丁语 dilatare“扩张”，由 dis-/di- 与 latus“宽”构成；可指瞳孔等扩大，也可指详尽论述。',C('dilate.s2','学术写作','When asked about the evidence, the lecturer began to dilate on the study’s limitations rather than giving a brief yes-or-no answer.','被问及证据时，讲师开始详细阐述研究的局限，而不是只给出简单的是或否。','When asked about the evidence / the lecturer began to dilate on the study’s limitations / rather than giving a brief yes-or-no answer.','dilate on/upon + 主题表示详述；begin to 后接动词原形。','讲师详细展开局限性，符合详述义 s2。'),M('The lecturer dilated on the issue by refusing to say anything further about it.','The lecturer declined to dilate on the issue and gave no further details.','拒绝补充内容不是详述；需改用 declined to dilate。'),[Q('dilate',1,1,'In medicine, pupils dilate when they?','become wider','close permanently','change into eyelashes','瞳孔 dilate 指扩张变大。'),Q('dilate',2,2,'To dilate on a point is to?','discuss it at length','erase it from a page','measure it with a thermometer','短语 dilate on 意为详细阐述。'),Q('dilate',3,1,'A doctor may use drops to make a patient’s pupils?','dilate','digress','disburse','扩瞳滴眼液使瞳孔扩大。'),Q('dilate',4,1,'Choose the correct collocation for the “elaborate” sense.','dilate on the reasons','dilate with the reasons','dilate at the reasons','详述某事常用 dilate on/upon。')]);
P('dilution','dilution 由 dilute + -ion 构成；dilute 源自拉丁语 diluere“冲淡、溶解”，指加液体降低浓度或由此产生的稀释液。',C('dilution.s1','实验室','The technician prepared a tenfold dilution by mixing one part of the stock solution with nine parts of water.','技术人员把一份储备液与九份水混合，配制成十倍稀释液。','The technician prepared a tenfold dilution / by mixing one part of the stock solution / with nine parts of water.','dilution 作名词；by + 动名词说明制备方法。','加水降低储备液浓度，体现稀释过程。'),M('Adding more water caused a dilution that made the solution ten times more concentrated.','Adding more water caused a dilution that made the solution less concentrated.','加水稀释会降低浓度，不会使溶液浓度增加。'),[Q('dilution',1,1,'Dilution of a solution usually involves?','adding solvent to reduce its concentration','removing all liquid to make it stronger','freezing it into a solid','稀释通常是加入溶剂降低浓度。'),Q('dilution',2,1,'A dilution may also refer to?','the weaker mixture produced','the original undiluted powder only','a device that measures distance','dilution 也可指稀释后形成的混合液。'),Q('dilution',3,1,'If juice tastes less sweet after water is added, it has undergone?','dilution','digestion','dictation','加水使味道变淡是稀释。'),Q('dilution',4,1,'Which change increases dilution?','adding water to concentrated juice','evaporating water from the juice','adding more concentrate','加水使溶液更稀。')]);
P('dimensional','dimensional 由 dimension + -al 构成；dimension 经法语、拉丁语 dimensio“测量”进入英语，可指维度数，也可指尺寸、空间测量相关。',C('dimensional.s2','工程设计','The engineer checked the dimensional tolerances on the drawing before machining the part, because a one-millimeter error would prevent assembly.','工程师加工零件前核对了图纸上的尺寸公差，因为一毫米误差就会导致无法装配。','The engineer checked the dimensional tolerances on the drawing / before machining the part / because a one-millimeter error would prevent assembly.','dimensional 修饰 tolerances；before + 动名词表示先后。','尺寸公差涉及零件的长宽等测量，符合 s2。'),M('The dimensional drawing listed no measurements, only the colour and the inventor’s favourite song.','The descriptive note listed no measurements, only the colour and the inventor’s favourite song.','没有任何尺寸数据的说明不能称 dimensional drawing。'),[Q('dimensional',1,1,'A three-dimensional object has?','length, width, and height','only colour and texture','no measurable size','三维包含长、宽、高。'),Q('dimensional',2,2,'Dimensional tolerances concern?','measurements and allowed size variation','religious belief','a person’s speaking voice','工程尺寸公差属于测量义。'),Q('dimensional',3,1,'A two-dimensional image has?','height and width but no represented depth','height, width, and physical depth','only a sound recording','二维图像表现高和宽，不呈现实体深度。'),Q('dimensional',4,1,'Which phrase is natural in engineering?','dimensional accuracy','dimensional yesterday','dimensional into silence','dimensional 可修饰 accuracy/tolerance。')]);
P('diminution','diminution 经古法语 diminution 源于拉丁语 deminuere“减少”，由 de- 与 minuere“变小”相关，指数量、体积或地位的减少。',C('diminution.s1','自然保护','The diminution of the wetland’s area over two decades forced nesting birds into smaller and more crowded patches.','二十年来湿地面积不断缩小，迫使筑巢的鸟类挤进更小、更拥挤的区域。','The diminution of the wetland’s area over two decades / forced nesting birds / into smaller and more crowded patches.','diminution of + 名词表示该事物的减少；force A into B 表结果。','湿地面积减少即数量/范围降低，体现词义。'),M('The diminution of the lake doubled its surface area and expanded the shoreline.','The enlargement of the lake doubled its surface area and expanded the shoreline.','面积加倍是扩大而不是减少；enlargement 符合结果。'),[Q('diminution',1,1,'A diminution in support means support?','has decreased','has doubled','has been replaced by a different subject','diminution 表示减少、缩小。'),Q('diminution',2,1,'Which phrase uses diminution naturally?','a diminution of the forest area','a diminution into a loud sound','a diminution of three new trees added','diminution 常接 of + 被减少的对象。'),Q('diminution',3,1,'The diminution of a budget would usually mean?','less money is available','funding has risen sharply','all accounts have closed','预算减少意味着可用资金降低。'),Q('diminution',4,1,'The closest opposite of diminution is?','increase','decline','reduction','increase 表示增加，与减少相反。')]);
P('diminutive','diminutive 经法语 diminutif 源自拉丁语 deminuere“变小”；作形容词指体型极小，也作名词指表达小巧或亲昵的词形。',C('diminutive.s2','语言学','In Spanish, the diminutive ending can make a noun sound smaller or more affectionate, though its exact effect depends on context.','在西班牙语中，指小词尾可使名词听起来更小巧或更亲昵，具体效果仍取决于语境。','In Spanish / the diminutive ending can make a noun sound smaller or more affectionate / though its exact effect depends on context.','diminutive 在此作名词定语；make + 宾语 + sound + 形容词。','指小后缀表达尺寸小或亲昵情感，符合 s2。'),M('The diminutive form made the noun sound larger and more formal in every context.','The augmentative form made the noun sound larger and more emphatic in some contexts.','指小形式不是表达更大；表示增大的形式为 augmentative。'),[Q('diminutive',1,1,'A diminutive animal is?','very small','unusually loud','fully grown and enormous','形容词义 diminutive 表示极小。'),Q('diminutive',2,2,'A linguistic diminutive may express?','smallness or affection','a verb’s past tense only','a plural number greater than two','名词义指表示小巧或亲昵的词形。'),Q('diminutive',3,1,'Which could be described as diminutive?','a tiny teacup','a towering water tank','a wide airport runway','非常小的茶杯可称 diminutive。'),Q('diminutive',4,2,'A nickname ending may function as a diminutive when it?','adds a sense of smallness or endearment','turns a noun into a question','marks a future tense','指小形式可增加亲昵意味。')]);
P('dimly','dimly 由 dim + -ly 构成；dim 的古英语词形意为暗淡，副词可指光线微弱，也可指记忆或理解模糊。',C('dimly.s2','回忆','I dimly remembered the seaside hotel from childhood, but I could not recall its name or the street where it stood.','我对童年时那家海边旅馆只有模糊印象，想不起名字，也记不得它所在的街道。','I dimly remembered the seaside hotel from childhood / but I could not recall its name / or the street where it stood.','dimly 修饰 remembered；but 表示记忆不清的结果。','记得不清、无法回想细节，体现记忆模糊义 s2。'),M('She dimly recalled every exact detail with perfect certainty and no gaps.','She clearly recalled every exact detail with perfect certainty and no gaps.','完全准确、毫无遗漏的回忆是清楚而非模糊的。'),[Q('dimly',1,1,'A room lit dimly is?','lit with weak, low light','brilliantly illuminated','completely outdoors','dimly 修饰光线，表示昏暗地。'),Q('dimly',2,2,'To remember dimly is to remember?','only vaguely','with perfect detail','not at all and never before','记忆义 dimly 表示模糊地记得。'),Q('dimly',3,1,'Which sentence uses dimly for light?','The lamp glowed dimly in the hallway.','He dimly remembered the appointment.','The map dimly explained the law.','灯光微弱使用光线义。'),Q('dimly',4,1,'Which is closest to “dimly understood”?','understood only vaguely','understood perfectly','did not hear at all','理解义 dimly 表示不充分、不清楚。')]);
P('dimply','dimply 由 dimple + -y 构成；dimple 经古英语/古日耳曼语中“凹痕、小坑”词族进入现代英语，dimply 指带有小酒窝或凹坑的。',C('dimply.s1','人物肖像','The child smiled dimply at the camera, and two small hollows appeared in her cheeks as her grandfather waved from behind it.','孩子对着镜头露出酒窝笑容，祖父在镜头后挥手时，她脸颊上现出两个小凹窝。','The child smiled dimply at the camera / and two small hollows appeared in her cheeks / as her grandfather waved from behind it.','dimply 作方式/外观副词性形容词；smile dimply 描写笑时带酒窝。','脸颊笑出小凹窝，符合 dimply 的“有酒窝的”义。'),M('He smiled dimply, but his face showed no dimples or small hollows at all.','He smiled broadly, but his face showed no dimples or small hollows at all.','dimply 明确涉及酒窝或小凹窝；无凹窝的笑容不符合该词。'),[Q('dimply',1,1,'A dimply smile is one that?','shows small hollows in the cheeks','has no visible facial movement','is made only in darkness','dimply 指笑时带有酒窝。'),Q('dimply',2,1,'Which feature might be described as dimply?','cheeks with small natural indentations','a perfectly smooth metal plate','a straight line across a page','脸颊的小凹窝可称 dimply。'),Q('dimply',3,1,'The base word of dimply is?','dimple','dimensional','diminution','dimply 由 dimple 派生。'),Q('dimply',4,1,'A baby’s dimply cheeks have?','tiny hollows or indentations','large scales','a uniform painted stripe','dimple 是小凹窝、酒窝。')]);
P('dinginess','dinginess 由 dingy + -ness 构成，表示暗淡、脏旧的外观或状态；dingy 的更早来源不确定，不进一步杜撰词根。',C('dinginess.s1','房屋卫生','A fresh coat of paint and brighter bulbs reduced the hallway’s dinginess, which had made the whole apartment feel neglected.','重新粉刷并换上更亮的灯泡，减轻了走廊的昏暗脏旧感；此前整套公寓都显得无人照料。','A fresh coat of paint and brighter bulbs reduced the hallway’s dinginess / which had made the whole apartment feel neglected.','dinginess 作不可数名词；which 引导定语从句修饰此前走廊状态。','粉刷和照明改善的是昏暗、脏旧的外观。'),M('The room’s dinginess came from spotless white walls, bright windows, and immaculate floors.','The room’s brightness came from spotless white walls, bright windows, and immaculate floors.','明亮洁净的室内与 dinginess 的昏暗肮脏相反。'),[Q('dinginess',1,1,'A room’s dinginess refers to its?','dull, grimy appearance','excellent acoustics','large floor area','dinginess 指暗淡、脏旧的外观。'),Q('dinginess',2,1,'Which change would reduce dinginess?','cleaning the walls and improving the light','covering the lamps and adding grime','closing every window permanently','清洁墙面、改善照明能减少脏暗感。'),Q('dinginess',3,1,'Dinginess is the noun form related to?','dingy','dignify','directional','dinginess 由形容词 dingy 加 -ness 构成。'),Q('dinginess',4,1,'A visitor notices dinginess in a neglected stairwell because it looks?','dark and dirty','newly polished','brightly decorated','昏暗而肮脏是 dingy 的特征。')]);
P('dingy','dingy 词源不确定；现代英语中指昏暗、肮脏而显得令人沮丧，也可指颜色褪去光泽、发暗。',C('dingy.s2','衣物颜色','The once-blue curtains had turned dingy after years of sunlight and smoke, so the owner replaced them before listing the flat.','曾经蓝色的窗帘经过多年日晒和烟熏变得黯淡褪色，房主挂牌出租前把它们换掉了。','The once-blue curtains had turned dingy after years of sunlight and smoke / so the owner replaced them / before listing the flat.','turn dingy 表示变得褪色发暗；before 引导先于挂牌的动作。','窗帘失去鲜亮颜色，体现 s2。'),M('The dingy curtains looked vivid and newly dyed, with every colour glowing brightly.','The vibrant curtains looked newly dyed, with every colour glowing brightly.','鲜亮、色彩明艳与 dingy 褪色发暗相反。'),[Q('dingy',1,1,'A dingy room is typically?','dark and dirty-looking','spotless and brilliantly lit','filled with fresh flowers only','dingy 常形容房间昏暗脏旧。'),Q('dingy',2,2,'A dingy blue shirt has?','a faded, dull shade of blue','a newly bright electric-blue colour','no colour because it is transparent','颜色义 dingy 指褪色发暗。'),Q('dingy',3,1,'Which setting could be called dingy?','a grimy basement with one weak bulb','a sunny clean kitchen with white walls','a newly painted gallery with skylights','脏旧、照明不足的地下室可称 dingy。'),Q('dingy',4,1,'The noun for a dingy appearance is?','dinginess','diction','dilution','dingy 的名词形式是 dinginess。')]);
P('dining','dining 是 dine 加 -ing 构成的动名词/名词；dine 通过法语、拉丁语源自晚期拉丁语 disjejunare“结束禁食”，可指用餐或宴会正餐。',C('dining.s2','正式宴请','The museum arranged formal dining for visiting scholars, with a seated meal and speeches after the exhibition closed.','博物馆为来访学者举行了正式宴会，展览结束后安排了入席用餐和致辞。','The museum arranged formal dining for visiting scholars / with a seated meal and speeches / after the exhibition closed.','dining 作宴餐名词时可与 formal 连用，指正式的社交正餐。','有座席、致辞的正式餐宴，体现 s2。'),M('They were dining at noon but watched a film and ate nothing.','They were meeting at noon but watched a film and ate nothing.','dining 表示吃正餐；看电影但完全没有进食的活动应称 meeting，而非用餐。'),[Q('dining',1,1,'Dining is the activity of?','eating a main meal','serving as a courtroom judge','repairing a roof','dining 作名词指进餐活动。'),Q('dining',2,2,'A formal dining may include?','a planned meal shared by invited guests','a quick snack eaten alone on a bus','a silent equipment inspection','s2 可指正式的社交宴餐。'),Q('dining',3,1,'A dining room is primarily a room for?','eating meals','sleeping outdoors','storing laboratory chemicals','dining room 是用餐的房间。'),Q('dining',4,1,'Which is a natural use of the verb form?','They were dining with the visiting professor.','They dining with the professor yesterday.','They have dining the professor.','were dining 是现在进行时结构。','grammar')]);
P('dire','dire 来自拉丁语 dirus“可怕、凶险”，经法语进入英语；指危急、可能导致灾难的，也可口语指质量极差。',C('dire.s1','紧急救援','The rescue team received a dire warning that the river would rise above the bridge before nightfall.','救援队接到紧急警告，河水将在夜幕降临前涨过桥面。','The rescue team received a dire warning / that the river would rise above the bridge / before nightfall.','dire 修饰 warning；that 引导警告的具体内容。','洪水可能超过桥面、威胁安全，属于危急严重情形。'),M('The town was in dire condition, but officials reported that no threat or urgent problem existed.','The town was in stable condition, and officials reported that no threat or urgent problem existed.','没有任何威胁或紧急问题时，不能称情势 dire。'),[Q('dire',1,1,'A dire situation is?','extremely serious and potentially disastrous','slightly inconvenient but harmless','pleasant and relaxing','dire 指严重、凶险或可能酿成灾难。'),Q('dire',2,2,'A critic says a film’s acting was dire. The critic means it was?','extremely poor','unusually moving and excellent','difficult to hear because of distance only','口语义 dire 表示质量极差。'),Q('dire',3,1,'Which news is most likely to be described as dire?','a hospital has almost run out of emergency oxygen','a shop has changed its opening hours','a café has added a new dessert','严重缺乏急救氧气是危急消息。'),Q('dire',4,1,'The word dire is closest to?','grave','minor','delightful','grave 有严重、危急之意。')]);
P('directional','directional 由 direction + -al 构成；direction 经古法语、拉丁语 dirigere“指引、使直行”发展而来，指与方向有关或主要朝某一方向作用。',C('directional.s1','工程标识','The directional signs at the station point toward the platforms, exits, and ticket hall so that new passengers can navigate the building.','车站的方向指示牌指向站台、出口和售票厅，方便新乘客在楼内辨路。','The directional signs at the station point toward the platforms, exits, and ticket hall / so that new passengers can navigate the building.','directional 修饰 signs；point toward 表示指向某处。','标识用来指出路径与方位，符合“方向性的”。'),M('A directional sign points nowhere and gives passengers no information about where to go.','A decorative sign points nowhere and gives passengers no information about where to go.','不指示方向的牌子不能称 directional；decorative 更贴切。'),[Q('directional',1,1,'A directional sign tells people?','which way to go','what a meal tastes like','how much a product costs','directional sign 提供方向信息。'),Q('directional',2,1,'A directional antenna may be designed to?','send or receive a stronger signal in one direction','work equally without regard to direction','measure the weight of a package','某方向信号更强，体现方向性。'),Q('directional',3,1,'Which phrase is correctly formed?','directional guidance','directional yesterday','directional of silently','directional 可修饰 guidance。'),Q('directional',4,1,'Directional is derived directly from which noun?','direction','dictionary','dignity','directional 由 direction 加 -al 构成。')]);
P('disabled','disabled 由 disable + -ed 构成；disable 经法语/拉丁语词族由 dis- + habilis“有能力的”构成，可指有身心障碍者，也指设备失灵或停用。',C('disabled.s2','网络安全','The administrator left the disabled account locked until the identity check was complete, preventing anyone from logging in during the investigation.','身份核验完成前，管理员一直锁定这个已停用账户，避免调查期间有人登录。','The administrator left the disabled account locked / until the identity check was complete / preventing anyone from logging in during the investigation.','disabled 修饰 account；leave + 宾语 + 形容词补语。','账户被设置为不能使用，符合“失灵/停用”义 s2。'),M('The disabled alarm could not operate, yet it sounded normally throughout the entire test.','The enabled alarm operated and sounded normally throughout the entire test.','如果设备无法运行，就不能同时正常报警；enabled 与实际功能一致。'),[Q('disabled',1,1,'A disabled person has?','a physical or mental impairment that limits daily activity','a temporary preference for a different colour','a role repairing all computers','disabled 的一义指有身心障碍者。'),Q('disabled',2,2,'A disabled computer function is?','made unable to operate','running at full capacity','newly installed and fully tested','设备义 disabled 表示被停用或无法工作。'),Q('disabled',3,1,'If a user account is disabled, the user usually?','cannot sign in until it is enabled','has unlimited access','has been given a new password automatically','停用账户无法正常登录。'),Q('disabled',4,1,'Which wording refers to an accessibility setting?','the disabled lift is out of service','the disabled citizens need no access','the disabled password is blue','disabled 可描述失灵的电梯/设备。')]);
P('disadvantageous','disadvantageous 由 disadvantage + -ous 构成，disadvantage 源于 dis-（不利）与 advantage；意为造成劣势或较差处境。',C('disadvantageous.s1','合同谈判','The short renewal window was disadvantageous to small suppliers, who needed more time to compare costs and arrange delivery.','很短的续约窗口期对小供应商不利，因为他们需要更多时间比较成本并安排交付。','The short renewal window was disadvantageous to small suppliers / who needed more time / to compare costs and arrange delivery.','be disadvantageous to + 人/群体；who 引导定语从句。','短期限使小供应商处于竞争劣势，符合词义。'),M('The deadline was disadvantageous to the team because it gave them extra weeks and reduced pressure.','The deadline was advantageous to the team because it gave them extra weeks and reduced pressure.','额外时间、压力降低带来有利条件，与 disadvantageous 相反。'),[Q('disadvantageous',1,1,'A disadvantageous decision?','puts someone in a worse position','provides a clear benefit','has no possible consequence','disadvantageous 指造成不利处境。'),Q('disadvantageous',2,1,'A contract term disadvantageous to a tenant may?','increase the tenant’s costs or risk','guarantee free repairs','remove all financial obligations','不利条款会增加成本或风险。'),Q('disadvantageous',3,1,'Choose the common preposition: “disadvantageous ___ small firms.”','to','at','from','固定搭配通常为 disadvantageous to。'),Q('disadvantageous',4,1,'The opposite of disadvantageous is?','advantageous','harmful','unfavourable','advantageous 表示有利，与之相反。')]);
P('disaffection','disaffection 由 dis-（缺乏/相反）和 affection 构成，源自拉丁语 affectio“倾向、感情”；指对机构或领导失去忠诚、产生不满。',C('disaffection.s1','公共治理','Growing disaffection with the council became clear when residents stopped attending meetings and organized a petition for new leadership.','居民不再参加会议并组织请愿要求更换领导，这表明他们对市政委员会日益不满。','Growing disaffection with the council became clear / when residents stopped attending meetings / and organized a petition for new leadership.','disaffection with + 组织表示对其不满；when 从句说明迹象。','居民失去支持并要求换届，体现不满和离心。'),M('Public disaffection grew after the council earned widespread trust and enthusiastic support.','Public confidence grew after the council earned widespread trust and enthusiastic support.','信任与热情支持表示忠诚满意，不是 disaffection。'),[Q('disaffection',1,1,'Disaffection toward a leader means?','loss of loyalty or growing dissatisfaction','complete trust and affection','a plan to build a road','disaffection 指不满、离心。'),Q('disaffection',2,1,'Which event may signal public disaffection?','many residents withdraw support and protest','voters express unanimous renewed trust','the council opens a new office','撤回支持并抗议表明不满。'),Q('disaffection',3,1,'The usual construction is “disaffection ___ the government.”','with','between','onto','常说 disaffection with an institution。'),Q('disaffection',4,1,'Disaffection is closest to?','alienation','devotion','approval','alienation 表示疏离，与不满离心相近。')]);
P('disagreeable','disagreeable 由 disagree + -able 构成；disagree 来自 dis- 与 agree，既可指味道、天气等令人不快，也可指人脾气难相处。',C('disagreeable.s2','人际关系','The new tenant was disagreeable at first, snapping at neighbours over small noises and refusing to discuss a shared cleaning rota.','新房客起初很难相处，为一点小噪声就冲邻居发火，还拒绝讨论共同清洁轮值表。','The new tenant was disagreeable at first / snapping at neighbours over small noises / and refusing to discuss a shared cleaning rota.','disagreeable 作表语形容词；并列动名词说明令人不快的行为。','对小事发火、拒绝协商体现难相处的人格义 s2。'),M('The agreeable neighbour insulted everyone and refused to speak politely.','The disagreeable neighbour insulted everyone and refused to speak politely.','辱骂别人、拒绝礼貌交谈体现难相处，应使用 disagreeable。'),[Q('disagreeable',1,1,'A disagreeable smell is?','unpleasant','fragrant and inviting','impossible to notice by definition','disagreeable 可形容令人不快的气味。'),Q('disagreeable',2,2,'A disagreeable person is often?','bad-tempered and unpleasant to be with','generous and easygoing','unknown to everyone','人义 disagreeable 指脾气差、难相处。'),Q('disagreeable',3,1,'Which weather might be called disagreeable?','cold rain and a biting wind','a mild sunny afternoon','a comfortable breeze','湿冷大风是令人不快的天气。'),Q('disagreeable',4,1,'The opposite of disagreeable in personality is?','pleasant','irritable','unpleasant','pleasant 表示令人愉快、好相处。')]);
P('disallow','disallow 由 dis-（否定）与 allow 构成；allow 经古法语源自拉丁语 allaudare“赞许”，disallow 指正式拒绝准许或不计入。',C('disallow.s1','体育规则','The referee disallowed the goal because the striker had touched the ball with a hand just before shooting.','裁判判进球无效，因为射门前前锋刚用手碰过球。','The referee disallowed the goal / because the striker had touched the ball with a hand / just before shooting.','disallow 作及物动词，宾语可为 goal；because 说明判罚理由。','裁判正式判定该进球不合规则、不予计入。'),M('The tournament disallowed the valid entry, so it officially accepted the score and counted it.','The tournament allowed the valid entry, so it officially accepted the score and counted it.','若赛事计入并接受分数，就没有 disallow 该成绩。'),[Q('disallow',1,1,'If a referee disallows a goal, the goal?','does not count under the rules','wins the match automatically','is moved to another field','disallow 表示正式判无效。'),Q('disallow',2,1,'A court may disallow evidence when it?','refuses to accept it for the case','adds it to the official record','sends it to a printer','法律语境中 disallow 可指不采纳证据。'),Q('disallow',3,1,'Choose the correct form: “The board ___ the claim.”','disallowed','disallowing yesterday','has disallow','一般过去时为 disallowed。','verb-form'),Q('disallow',4,1,'Disallow is closest to?','reject as impermissible','approve officially','pay out','disallow 意为拒绝准许或驳回。')]);
P('disappearance','disappearance 由 disappear + -ance 构成，disappear 是 dis- 加 appear；指消失这一动作，或某人失踪的事件。',C('disappearance.s1','寻人通报','The disappearance of the hiker was reported at dusk, and a search team began checking the marked trails before the weather worsened.','黄昏时有人报告徒步者失踪，天气转坏前搜救队开始检查已标记的步道。','The disappearance of the hiker was reported at dusk / and a search team began checking the marked trails / before the weather worsened.','disappearance of + 人指其失踪；before 引导行动时间。','徒步者未按时出现并启动搜寻，符合失踪事件义。'),M('The disappearance of the missing child was announced, although the child was standing safely beside the reporter.','The recovery of the missing child was announced, as the child was standing safely beside the reporter.','人已找到并在场不再是失踪；recovery 描述安全寻回。'),[Q('disappearance',1,1,'The disappearance of a person means?','the person has gone missing or vanished','the person has been promoted','the person has arrived on schedule','disappearance 可指人员失踪。'),Q('disappearance',2,1,'A disappearance of stars at dawn may occur because?','daylight makes them no longer visible','the stars physically fall into the sea','the sky has become a solid object','可见性消失不一定意味着物体不存在。'),Q('disappearance',3,1,'Which collocation is natural?','the sudden disappearance of the files','the disappearance to the files','the disappearance among yesterday','常见结构是 disappearance of。'),Q('disappearance',4,1,'Investigators looking into a disappearance are trying to learn?','where and how someone vanished','how to grow a plant','why a currency changed its value','调查失踪事件需查明人如何失去踪迹。')]);
P('disappointed','disappointed 是 disappoint 的过去分词形容词；disappoint 经古法语词族由 dis- 与 appoint 构成，描述期待落空后感到不开心。',C('disappointed.s1','考试成绩','Mina was disappointed with her score, but she reviewed the missed questions and made a plan for the next exam.','米娜对自己的分数感到失望，但她复盘错题并为下一次考试制订计划。','Mina was disappointed with her score / but she reviewed the missed questions / and made a plan for the next exam.','be disappointed with + 结果表示对结果失望；but 表示转而行动。','成绩未达预期引发不开心，符合 disappointed。'),M('He was disappointed with the excellent result because it was exactly what he had hoped for.','He was pleased with the excellent result because it was exactly what he had hoped for.','完全符合期待的好结果通常让人满意而非失望。'),[Q('disappointed',1,1,'A disappointed person feels unhappy because?','expectations were not met','everything went exactly as hoped','a meal was served on time','disappointed 描述期待落空后的情绪。'),Q('disappointed',2,1,'Which phrase is standard?','disappointed with the result','disappointed at the result from','disappointed by to the result','常用 be disappointed with/about the result。','collocation'),Q('disappointed',3,1,'If a fan is disappointed by a cancelled concert, the fan?','had hoped to attend it','never knew the concert existed','is guaranteed a better show','取消演出使期待落空。'),Q('disappointed',4,1,'Disappointed describes?','the person feeling let down','the thing causing the feeling only','a future promise','disappointed 通常描述感到失望的人。')]);
P('disappointing','disappointing 是 disappoint 的现在分词形容词，表示未达到期望、因而令人失望；词源与 disappointed 同。',C('disappointing.s1','产品评价','The camera’s disappointing battery life meant that it shut down halfway through the trip, despite being fully charged at breakfast.','这台相机令人失望的续航让它在旅程中途关机，尽管早餐时刚充满电。','The camera’s disappointing battery life meant that it shut down halfway through the trip / despite being fully charged at breakfast.','disappointing 修饰 battery life，描述造成感受的事物；despite 后接动名词。','续航表现不如期待、导致旅途中关机，符合令人失望。'),M('The disappointing report exceeded every target and delighted the entire team.','The impressive report exceeded every target and delighted the entire team.','超额达标且令团队高兴的报告不令人失望。'),[Q('disappointing',1,1,'A disappointing performance?','fails to be as good as people hoped','exceeds every expectation','has no audience at all','disappointing 描述造成失望的表现。'),Q('disappointing',2,1,'A disappointing result is likely to leave people?','unhappy or let down','completely unsurprised in a positive way','unable to read numbers','结果低于期待会使人失望。'),Q('disappointing',3,1,'Choose the sentence with the correct contrast.','The film was disappointing, so several viewers left early.','The film was disappointing because everyone loved it and demanded a sequel.','The film disappointedly is a noun.','观众提前离场与影片令人失望相符。'),Q('disappointing',4,1,'The -ing form usually describes?','the thing that causes the feeling','the person experiencing the feeling only','a completed past action','disappointing 描述令人产生该情绪的事物。')]);
P('disappointment','disappointment 由 disappoint + -ment 构成；disappoint 源自古法语词族；名词可指期待落空的情绪，也指不如预期的人或事。',C('disappointment.s2','赛事结果','The tournament’s biggest disappointment was the defending champion, who lost every match despite months of preparation.','赛事中最令人失望的当属卫冕冠军：尽管准备了数月，他还是输掉了每一场比赛。','The tournament’s biggest disappointment was the defending champion / who lost every match / despite months of preparation.','disappointment 作可数名词，指令人失望的人/事；who 引导定语从句。','失利的卫冕冠军被称为最令人失望的人物，体现 s2。'),M('Her disappointment was the happiest surprise of the year and exceeded all her hopes.','Her delight was the happiest surprise of the year and exceeded all her hopes.','超出期待的快乐惊喜是 delight，不是 disappointment。'),[Q('disappointment',1,1,'Disappointment is the feeling of?','sadness when a hoped-for result fails to happen','joy because a wish came true','confusion about a map','情绪义是期待未实现后的失落。'),Q('disappointment',2,2,'Calling a performance “a disappointment” means it?','was not as good as expected','was the best anyone had ever seen','was never performed','s2 表示令人失望的人或事。'),Q('disappointment',3,1,'Which phrase is natural?','a source of disappointment','a disappointment to happenly','a disappointment of quickly','可说 a source of disappointment。'),Q('disappointment',4,1,'If a postponed trip causes disappointment, the traveller feels?','sad because the plan did not occur','proud of a new skill','hungry for lunch','计划未实现引起失望情绪。')]);
P('disapproval','disapproval 由 disapprove + -al 构成，disapprove 含 dis- 与 approve；既指不赞成的意见，也指表现出反对的态度。',C('disapproval.s2','家庭交往','When her son announced the reckless plan, his father’s disapproval was obvious: he folded his arms and shook his head.','儿子宣布这个鲁莽计划时，父亲的不赞成显而易见：他抱起双臂并摇头。','When her son announced the reckless plan / his father’s disapproval was obvious / he folded his arms and shook his head.','disapproval 可作具体态度名词；冒号后解释其外在表现。','摇头和抱臂是表明不赞同的行为，符合 s2。'),M('The committee showed disapproval by applauding the proposal and voting unanimously to approve it.','The committee showed approval by applauding the proposal and voting unanimously to adopt it.','鼓掌并一致通过是在表达赞同，不是反对。'),[Q('disapproval',1,1,'Disapproval means?','the opinion that something is wrong or unsuitable','formal praise','a payment made to a supplier','disapproval 表示不赞成的看法。'),Q('disapproval',2,2,'A frown and a head shake can show?','disapproval','a signed contract','a diagnosis','非语言行为可以表现反对态度。'),Q('disapproval',3,1,'Which verb commonly collocates with disapproval?','express','digest','disburse','常说 express/show disapproval。'),Q('disapproval',4,1,'A sign of disapproval is most likely?','a disapproving gesture','a congratulatory hug','a cheerful thumbs-up','反对的手势表明不赞同。')]);
P('disarmament','disarmament 由 disarm + -ment 构成，disarm 来自 dis- + arm（武装）；指削减或放弃军事武器。',C('disarmament.s1','国际关系','The two neighbours began a disarmament program by removing heavy weapons from the border and inviting inspectors to verify the reductions.','两个邻国启动裁军计划，先从边境撤走重型武器，并邀请检查员核实削减情况。','The two neighbours began a disarmament program / by removing heavy weapons from the border / and inviting inspectors to verify the reductions.','disarmament 作名词；by + 动名词说明裁军方式。','撤走军事武器并核查削减，体现 disarmament。'),M('The disarmament agreement required both sides to buy more weapons and expand their arsenals.','The rearmament agreement required both sides to buy more weapons and expand their arsenals.','扩充武器属于 rearmament（重新武装），与裁军相反。'),[Q('disarmament',1,1,'Disarmament is the process of?','reducing or giving up weapons','adding more weapons to an arsenal','training new pilots','disarmament 指裁减或放弃武器。'),Q('disarmament',2,1,'A disarmament treaty may require countries to?','remove specified arms and verify the cuts','increase every weapon stockpile','hide weapons from inspectors','条约可能规定削减武器并接受核查。'),Q('disarmament',3,1,'The prefix dis- in disarmament signals?','removal or reversal of armament','an increase in weapons','a place where arms are made','disarm 表示解除武装。'),Q('disarmament',4,1,'The opposite process is?','rearmament','devaluation','disappearance','rearmament 是重新扩充武装。')]);
P('disarming','disarming 由 disarm + -ing 构成；disarm 字面为解除武装，转义为使人放下戒心，也可指缓和怒意或敌意。',C('disarming.s1','初次会面','Her disarming smile put the nervous interview panel at ease, and they began asking questions in a more relaxed tone.','她那亲切得令人卸下戒心的微笑让紧张的面试小组放松下来，大家随后语气也轻松了些。','Her disarming smile put the nervous interview panel at ease / and they began asking questions / in a more relaxed tone.','disarming 修饰 smile；put A at ease 表示使 A 放松。','亲切笑容减少戒备心理，符合 s1。'),M('His disarming manner made everyone more suspicious and eager to keep their distance.','His intimidating manner made everyone more suspicious and eager to keep their distance.','加深怀疑并令人疏远不是使人卸下戒心；intimidating 更贴切。'),[Q('disarming',1,1,'A disarming manner makes people feel?','friendly and less suspicious','more armed for battle','certain that a threat is imminent','disarming 比喻使人放松戒备。'),Q('disarming',2,2,'A joke can have a disarming effect on anger when it?','reduces hostility in the room','makes everyone angrier','starts a physical fight','disarming 也可表示缓和敌意。'),Q('disarming',3,1,'Which smile is disarming?','a warm smile that makes a shy guest relax','a threatening glare that frightens a guest','a blank look that hides every response','亲切笑容使人放松。'),Q('disarming',4,1,'The literal idea behind disarming is to?','remove weapons or defenses','give someone a new weapon','build a barrier','词形本义与解除武装有关，引申为解除戒心。')]);
P('disarrange','disarrange 由 dis- 与 arrange 构成，表示打乱物品的秩序，也可指扰乱既定计划或安排。',C('disarrange.s2','日程安排','The airline’s cancellation disarranged our travel plans, forcing us to book a later train and move the hotel reservation.','航空公司取消航班打乱了我们的行程，迫使我们改订晚些的火车并调整酒店预订。','The airline’s cancellation disarranged our travel plans / forcing us to book a later train / and move the hotel reservation.','disarrange 作及物动词；force + 宾语 + to do 表示迫使。','航班取消扰乱安排，符合 s2。'),M('The unexpected storm disarranged the schedule but left every event exactly on time.','The unexpected storm disrupted the schedule and delayed several events.','若每项活动都准时进行，安排并未被打乱；改为延误以符合 disarrange。'),[Q('disarrange',1,1,'To disarrange a desk is to?','put its contents out of order','organize every item neatly','throw away the desk','disarrange 指弄乱物品的秩序。'),Q('disarrange',2,2,'A cancellation can disarrange a plan by?','forcing changes to the schedule','confirming every booking','making the original timing certain','取消会扰乱并改变安排。'),Q('disarrange',3,1,'Which object can be disarranged?','a carefully arranged set of files','a person’s height','a chemical element’s atomic number only','文件排列可以被打乱。'),Q('disarrange',4,1,'Disarrange is closest to?','disrupt','sort','repair','disrupt 表示扰乱，意思接近。')]);
P('disarray','disarray 由 dis- 与 array（排列）构成；作名词指缺乏秩序、混乱，也可作动词指使人或物陷入混乱。',C('disarray.s2','比赛组织','A last-minute venue change disarrayed the tournament schedule, leaving teams unsure which court to use for their opening matches.','最后时刻更换场馆打乱了赛事日程，参赛队伍不知道首场比赛该去哪个球场。','A last-minute venue change disarrayed the tournament schedule / leaving teams unsure / which court to use for their opening matches.','disarray 作及物动词；leave + 宾语 + 形容词表示使处于某状态。','临时变化使日程紊乱，使用动词义 s2。'),M('The office was in disarray because every file had been labelled, sorted, and returned to its correct shelf.','The office was orderly because every file had been labelled, sorted, and returned to its correct shelf.','文件全部分类归位体现井然有序，而非 disarray。'),[Q('disarray',1,1,'A room in disarray is?','untidy and lacking order','perfectly organized','empty of all furniture by definition','disarray 名词指混乱无序。'),Q('disarray',2,2,'To disarray a timetable is to?','throw it into disorder','print a clean copy','translate it into another language','动词 disarray 意为使计划紊乱。'),Q('disarray',3,1,'Which phrase is idiomatic?','in complete disarray','at a disarray to','disarray from five','常用 in disarray。','collocation'),Q('disarray',4,1,'A company may be left in disarray after?','a sudden crisis disrupts its operations','all its procedures work smoothly','a routine meeting ends on time','突发危机可能造成组织混乱。')]);
P('disavowal','disavowal 由 disavow + -al 构成；disavow 来自古法语 desavouer（否认、拒认），指公开拒绝承认知情、支持或责任。',C('disavowal.s1','政治声明','The minister issued a public disavowal of the campaign, saying he had never authorized its messages or used public funds for it.','部长公开否认支持该竞选活动，称自己从未批准那些信息，也没有为其动用公款。','The minister issued a public disavowal of the campaign / saying he had never authorized its messages / or used public funds for it.','disavowal of + 对象表示拒绝承认支持；saying 补充声明内容。','声明拒绝承认授权或资助，符合拒认义。'),M('Her disavowal accepted full responsibility for the act and proudly claimed she had ordered it.','Her admission accepted full responsibility for the act and acknowledged she had ordered it.','承认责任并称自己下令，与 disavowal（拒认）相反。'),[Q('disavowal',1,1,'A disavowal of a policy is?','a public refusal to accept or support it','a detailed plan to promote it','a payment toward it','disavowal 指公开否认或拒绝支持。'),Q('disavowal',2,1,'A leader may issue a disavowal to deny?','knowledge of or responsibility for an action','the existence of a calendar','a verified election result by counting votes','声明可拒认对行为知情或负责。'),Q('disavowal',3,1,'Which verb naturally collocates with disavowal?','issue','dilapidate','digest','常说 issue/make a disavowal。'),Q('disavowal',4,1,'Disavowal is closest to?','repudiation','endorsement','payment','repudiation 表示公开拒绝承认、接受。')]);
P('disbelief','disbelief 由 dis- 与 belief 构成，belief 与 believe 同源；指无法或拒绝相信某事，也可表示怀疑。',C('disbelief.s1','意外消息','She stared in disbelief when the tiny local team defeated the national champions by five goals in the final.','当地小球队在决赛中以五球优势击败全国冠军时，她难以置信地盯着比分看。','She stared in disbelief / when the tiny local team defeated the national champions / by five goals in the final.','in disbelief 作方式状语；when 引出令人惊讶的事件。','大冷门导致旁观者一时难以相信，符合 disbelief。'),M('He accepted the impossible story with disbelief and never doubted a single detail.','He accepted the story with belief and never doubted a single detail.','毫不怀疑地接受故事体现相信，不是 disbelief。'),[Q('disbelief',1,1,'A person in disbelief?','cannot readily accept that something is true','is certain a claim is correct','has just received a payment','disbelief 表示不相信或难以置信。'),Q('disbelief',2,1,'Which reaction shows disbelief?','“That cannot be true,” she said, rereading the message.','“I knew it was true all along,” he said.','“Please send the invoice,” she wrote.','反复确认消息且表示不可能，表现难以置信。'),Q('disbelief',3,1,'Which preposition commonly follows stare?','in disbelief','on disbelief','at disbelief to','惯用说法是 stare in disbelief。','collocation'),Q('disbelief',4,1,'The closest opposite of disbelief is?','belief','surprise','confusion','belief 是相信，与不相信相反。')]);
P('disburse','disburse 经古法语源自拉丁语 bursa“钱袋”，由 dis- 与 bursare（付钱）构成；指从已收集的资金中拨款支付。',C('disburse.s1','公共资金','The agency will disburse the grant in three instalments after recipients submit receipts showing that each stage is complete.','受助者提交证明各阶段完成的收据后，该机构将分三期拨付补助金。','The agency will disburse the grant in three instalments / after recipients submit receipts / showing that each stage is complete.','disburse 作及物动词，宾语为资金；in instalments 表示分期。','机构从专项资金中支付补助，符合拨付义。'),M('The foundation disbursed the grant by collecting money from the recipients and adding it to its own account.','The foundation collected the grant by receiving money from the recipients and adding it to its own account.','disburse 是付出已收集资金，不是向付款人收钱。'),[Q('disburse',1,1,'To disburse funds is to?','pay them out to the people entitled to receive them','borrow them from a bank','hide them from the accounting office','disburse 指拨款支付。'),Q('disburse',2,1,'A charity may disburse donations to?','families approved for emergency aid','the people who are collecting donations for themselves only','a dictionary publisher','慈善组织把款项发给获得援助的人。'),Q('disburse',3,1,'Which noun is a natural object of disburse?','funds','a shadow','an adjective','常说 disburse funds/money/grants。'),Q('disburse',4,1,'The finance office disbursed the money after?','checking the approved invoices','receiving an unrelated weather report','the money had been erased','核实获批发票后支付款项。')]);
P('disc','disc 经法语 disque 源自拉丁语 discus、希腊语 diskos“圆盘”；可指平圆物体、储存音乐/数据的唱片或光盘，也可作动词表示录制到盘片上。',C('disc.s2','音乐媒介','The band released its first disc on vinyl, and collectors lined up at the shop to buy the album on opening day.','乐队发行了首张黑胶唱片，收藏者在开售日排队到店购买专辑。','The band released its first disc on vinyl / and collectors lined up at the shop / to buy the album on opening day.','disc 作可数名词；on vinyl 指以黑胶形式发行。','黑胶唱片储存并播放音乐，符合 s2。'),M('The band released a disc on vinyl that was a square sheet with no recorded music.','The band released a disc on vinyl that was a round record containing recorded music.','唱片为圆盘并储存音乐；无录音的方形片材不符合 disc 此义。'),[Q('disc',1,1,'A metal disc is a?','flat, round object','long hollow tube','soft square pillow','disc 的一般义是扁平圆盘。'),Q('disc',2,2,'A music disc stores?','recorded sound or music','fresh food','a person’s handwriting only','唱片或光盘可储存音乐。'),Q('disc',3,3,'To disc a performance is to?','record it onto a disc','erase every instrument','perform it without sound','动词 disc 可表示录制到盘片上。'),Q('disc',4,1,'A compact disc is shaped like?','a flat circle','a triangular box','a long cylinder','光盘是扁平圆盘。')]);
P('discernible','discernible 由 discern + -ible 构成；discern 源于拉丁语 discernere“区分、辨别”，意为能够看出、察觉或识别的。',C('discernible.s2','数据分析','After the software removed background noise, a discernible pattern emerged: errors increased whenever the room temperature rose.','软件去除背景噪声后，出现了可辨认的规律：室温上升时错误就会增加。','After the software removed background noise / a discernible pattern emerged / errors increased whenever the room temperature rose.','discernible 修饰 pattern；whenever 引导重复发生条件。','数据趋势可以被观察辨认，符合 s2。'),M('There was a discernible difference between the identical values, although no measurement or comparison showed one.','There was no discernible difference between the identical values, and no measurement showed one.','数值完全相同且无测量差异，便没有可辨认的区别。'),[Q('discernible',1,1,'A discernible mark is?','able to be seen or noticed','impossible to detect','made entirely of sound','discernible 指可察觉、可看出的。'),Q('discernible',2,2,'A discernible pattern in data is?','a pattern that can be identified','a random mark no one can observe','a hidden file that does not exist','s2 强调可辨认的差别或规律。'),Q('discernible',3,1,'Which phrase is natural?','a discernible change in temperature','a discernible beyond the roof','a discernible without changing','discernible 可修饰 change。'),Q('discernible',4,1,'A sound too faint to hear is not?','discernible','audible','recorded','无法听见则不可察觉。')]);
P('discerning','discerning 由 discern + -ing 构成；discern 源自拉丁语 discernere“辨别”，形容能看出细微差别、判断质量好坏，也可指眼光挑剔而在行。',C('discerning.s2','消费选择','A discerning collector compared the paper, binding, and printing before buying the rare book, refusing to pay for a poor copy.','一位有眼光的收藏者购买珍本前比较纸张、装订和印刷质量，拒绝为劣本付钱。','A discerning collector compared the paper, binding, and printing before buying the rare book / refusing to pay for a poor copy.','discerning 修饰 collector；before + 动名词表示购买前的判断。','收藏者能辨别版本质量、挑选珍品，符合 s2。'),M('The discerning buyer chose a visibly damaged copy without examining it and ignored every quality difference.','The careless buyer chose a visibly damaged copy without examining it and ignored every quality difference.','不检查品质且忽略明显差异表现粗心，而不是有辨别力。'),[Q('discerning',1,1,'A discerning judge can?','recognize subtle differences in quality','confuse every option','choose randomly without looking','discerning 指有辨别力、眼光好。'),Q('discerning',2,2,'A discerning customer is careful because the customer?','knows what quality to look for','never compares products','buys the first item regardless of quality','有见识的顾客会依据质量标准选择。'),Q('discerning',3,1,'Which decision shows a discerning eye?','checking the stitching before choosing a coat','buying a coat with a torn seam without noticing','choosing solely by package size','检查做工体现鉴别能力。'),Q('discerning',4,1,'The closest synonym for discerning is?','perceptive','careless','indiscriminate','perceptive 表示有洞察力。')]);
P('discernment','discernment 由 discern + -ment 构成；discern 源自拉丁语 discernere“区分”，名词指辨别细微重要差异的敏锐判断力。',C('discernment.s1','编辑判断','The editor showed discernment by keeping the witness’s brief hesitation, a small detail that changed how readers understood the answer.','编辑展现出洞察力，保留了证人短暂犹豫这一细节；它改变了读者对回答的理解。','The editor showed discernment by keeping the witness’s brief hesitation / a small detail / that changed how readers understood the answer.','show discernment by + 动名词；that 从句说明细节的作用。','看出微小但关键的犹豫影响理解，体现敏锐判断。'),M('The editor showed discernment by overlooking every important clue and treating all details as identical.','The editor showed poor judgement by overlooking every important clue and treating all details as identical.','忽视关键线索、看不出细节差别表现判断力差。'),[Q('discernment',1,1,'Discernment is the ability to?','notice important differences and judge wisely','remember every date without understanding','move quickly across a room','discernment 指敏锐辨别和判断能力。'),Q('discernment',2,1,'A person with discernment may recognize?','a small but meaningful change in someone’s tone','only the largest object in a room','a number without seeing it','洞察力可帮助发现微小但重要的信号。'),Q('discernment',3,1,'Which quality most contrasts with discernment?','poor judgement','insight','perceptiveness','判断失准与 discernment 相反。'),Q('discernment',4,1,'A hiring panel uses discernment when it?','weighs evidence carefully instead of relying on first impressions','chooses a candidate by a coin toss','ignores all relevant experience','审慎权衡证据体现 discernment。')]);
P('disciple','disciple 经古法语 desciple 源于拉丁语 discipulus“学生、追随者”，与 discere“学习”相关；指追随宗教/哲学导师的人，也可泛指某理念的拥护者。',C('disciple.s2','思想流派','She became a disciple of the economist’s market theory, defending its principles in articles even when other researchers challenged them.','她成了这位经济学家市场理论的追随者，即使其他研究者提出质疑，她仍在文章中捍卫其原则。','She became a disciple of the economist’s market theory / defending its principles in articles / even when other researchers challenged them.','disciple of + 导师/理论；defending 说明其追随表现。','追随并捍卫某人的理论，体现泛指信徒、拥护者的 s2。'),M('A disciple of the teacher rejected every lesson, opposed the teacher’s ideas, and never followed the school.','An opponent of the teacher rejected every lesson, opposed the teacher’s ideas, and never followed the school.','反对并拒绝追随导师的人是 opponent，不是 disciple。'),[Q('disciple',1,1,'A religious disciple is?','a follower of a religious teacher','a person who rejects every teaching','a device for recording speech','disciple 指宗教导师的门徒。'),Q('disciple',2,2,'A disciple of a political theory is?','an enthusiastic supporter of that theory','a professional who diagnoses illness','a person who has never heard of it','s2 可泛指某理论的追随者或拥护者。'),Q('disciple',3,1,'Which phrase is correct?','a disciple of the philosopher','a disciple from the theory for','a disciple at yesterday','常见搭配为 disciple of a teacher/idea。','collocation'),Q('disciple',4,1,'The word disciple is historically related to?','learning from a teacher','measuring a circle’s diameter','reducing a currency’s value','disciple 的拉丁词源与学习有关。')]);

})();
